-- NEXA: part 5 of the setup. GENERATED by scripts/build-setup-sql.sh, do not edit.
-- Run the parts in order in the Supabase SQL Editor, one after the other.
begin;


-- ===== supabase/migrations/20261114000200_m3c_markets.sql =====
-- =============================================================================
-- NEXA · M3c · 0200 · Player-driven markets (ADR-056, docs/SIMULATION.md 6a)
-- =============================================================================
-- Mirrors src/lib/sim/player-influence.ts and tick.ts (stepSecurity):
--   * player orders move prices in euros: r = 0.01 x net value / depthCentsPer100Bps / liquidity
--   * value funds accept fair value x (1 + maxHoldingsPremium x tanh(held value / (premiumScaleDepths x depth)))
--   * momentum, retail herd and noise are weighted with w = max(minAiWeight, R / (R + player activity))
--   * bonds: noise x bonds.volatilityMultiplier, player orders in euros
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

alter table public.security_sim_state
  add column if not exists player_activity    double precision not null default 0,
  add column if not exists pending_player_volume_e6 bigint not null default 0;
comment on column public.security_sim_state.player_activity is 'Player traded value in cents (a decayed statistic, not money: double precision) with an exponential half-life (aiInvestors.playerWeight.activityHalfLifeHours); weakens the AI traders.';
comment on column public.security_sim_state.pending_player_volume_e6 is 'Gross player volume (millionths of a share) since the last tick; feeds player_activity.';

-- execute_fill as in M2, plus the gross player volume for the tick
create or replace function public.execute_fill(
  p_order_id    uuid,
  p_quantity bigint,
  p_price_e4    bigint,
  p_resting     boolean default false,
  p_system      boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  o            public.orders;
  s            public.securities;
  v_trading    jsonb := coalesce(public.config_jsonb('trading'), '{}'::jsonb);
  v_prog       jsonb := coalesce(public.config_jsonb('progression'), '{}'::jsonb);
  v_now        timestamptz := public.game_now();
  v_cash       uuid;
  v_reserve    uuid;
  v_counter    uuid;
  v_treasury   uuid;
  v_counter_ok boolean;
  v_counter_bal bigint;
  v_gross      bigint;
  v_fee        bigint := 0;
  v_tax        bigint := 0;
  v_pnl        bigint;
  v_cost       bigint := 0;
  v_release    bigint := 0;
  v_cash_delta bigint;
  v_balance    bigint;
  v_pos        public.positions;
  v_basis_new  bigint;
  v_avg_new    bigint;
  v_trade_id   uuid := gen_random_uuid();
  v_tx         uuid;
  v_xp         integer := 0;
  v_wash       boolean := false;
  v_first      boolean;
  v_pot        bigint;
  v_offset     bigint;
  v_left       bigint;
  v_take       bigint;
  v_entries    jsonb;
  v_tick_seq   bigint;
  v_year       integer;
  lot          record;
begin
  select * into o from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'order % does not exist', p_order_id using errcode = 'NX007';
  end if;
  if p_quantity is null or p_quantity <= 0 or p_quantity > o.quantity_e6 - o.filled_quantity_e6 then
    raise exception 'invalid fill quantity % for order %', p_quantity, p_order_id using errcode = 'NX007';
  end if;
  if p_price_e4 is null or p_price_e4 <= 0 then
    raise exception 'invalid fill price %', p_price_e4 using errcode = 'NX007';
  end if;
  select * into s from public.securities where id = o.security_id;
  v_first := o.filled_quantity_e6 = 0;

  v_gross := public.value_cents(p_quantity, p_price_e4);
  if o.fee_cents = 0 and not p_system then
    v_fee := greatest(0, public.cfg_num(v_trading, '{orderFeeCents}', 100))::bigint;
  end if;
  v_cash     := public.ledger_player_account(o.player_id, 'player_cash');
  v_reserve  := public.ledger_player_account(o.player_id, 'player_reserve');
  v_treasury := public.ledger_system_account('treasury');
  v_counter  := case when s.kind = 'bond' then v_treasury else public.ledger_system_account('market') end;
  select a.balance_cents into v_balance from public.ledger_accounts a where a.id = v_cash;
  select a.balance_cents, a.allow_negative into v_counter_bal, v_counter_ok from public.ledger_accounts a where a.id = v_counter;

  select * into v_pos
    from public.positions p
   where p.player_id = o.player_id and p.security_id = o.security_id
     and p.side = 'long' and p.leverage = 1 and p.status = 'open'
     for update;

  if o.side = 'buy' then
    if p_resting then
      v_release := o.reserved_cents;
    end if;
    v_cash_delta := v_release - v_gross - v_fee;
    if v_balance + v_cash_delta < 0 then
      perform public.api_error('insufficient_funds');
    end if;
    if v_pos.id is null then
      insert into public.positions (player_id, security_id, quantity_e6, avg_entry_price_e4, cost_basis_cents, opened_at)
      values (o.player_id, o.security_id, 0, p_price_e4, 0, v_now)
      returning * into v_pos;
    end if;
  else
    if v_pos.id is null
       or v_pos.quantity_e6 < p_quantity
       or (not p_resting and v_pos.quantity_e6 - v_pos.reserved_quantity_e6 < p_quantity)
       or (p_resting and v_pos.reserved_quantity_e6 < p_quantity) then
      perform public.api_error('insufficient_position');
    end if;
    -- the financial market (or the treasury for bonds) must be able to pay
    v_counter_bal := v_counter_bal - v_gross;
    if v_counter = v_treasury then
      v_counter_bal := v_counter_bal + v_fee;
    end if;
    if not v_counter_ok and v_counter_bal < 0 then
      perform public.api_error('market_illiquid');
    end if;
    v_left := p_quantity;
    for lot in
      select l.id, l.quantity_open_e6
        from public.position_lots l
       where l.position_id = v_pos.id and l.quantity_open_e6 > 0
       order by l.acquired_at, l.id
         for update
    loop
      exit when v_left = 0;
      v_take := least(v_left, lot.quantity_open_e6);
      update public.position_lots
         set quantity_open_e6 = quantity_open_e6 - v_take,
             closed_at = case when quantity_open_e6 - v_take = 0 then v_now else closed_at end
       where id = lot.id;
      v_left := v_left - v_take;
    end loop;
    select coalesce(sum(public.value_cents(l.quantity_open_e6, l.price_e4)), 0)::bigint
      into v_basis_new
      from public.position_lots l where l.position_id = v_pos.id and l.quantity_open_e6 > 0;
    v_cost := v_pos.cost_basis_cents - v_basis_new;
    if v_left > 0 then
      v_cost := v_cost + public.value_cents(v_left, v_pos.avg_entry_price_e4);
    end if;
    v_cost := greatest(v_cost, 0);

    v_pnl := v_gross - v_fee - v_cost;
    select pp.tax_loss_pot_cents into v_pot
      from public.player_private pp where pp.player_id = o.player_id for update;
    v_pot := coalesce(v_pot, 0);
    if v_pnl <= 0 then
      v_pot := v_pot - v_pnl;
    else
      v_offset := least(v_pnl, v_pot);
      v_tax := public.apply_bps(v_pnl - v_offset, public.cfg_num(v_trading, '{capitalGainsTaxBps}', 2500)::numeric);
      v_pot := v_pot - v_offset;
    end if;
    update public.player_private set tax_loss_pot_cents = v_pot where player_id = o.player_id;

    v_cash_delta := v_gross - v_fee - v_tax;
    if v_balance + v_cash_delta < 0 then
      perform public.api_error('insufficient_funds');
    end if;
    v_wash := exists (
      select 1 from public.trades t
       where t.player_id = o.player_id and t.security_id = o.security_id and t.side = 'buy'
         and t.executed_at > v_now - make_interval(secs => public.cfg_num(v_trading, '{washTradeWindowSeconds}', 600)));
  end if;

  -- ledger: one balanced transaction per fill (entries on the same account merged)
  select coalesce(jsonb_agg(jsonb_build_object('account_id', x.account_id, 'amount_cents', x.amount)), '[]'::jsonb)
    into v_entries
    from (select e.account_id, sum(e.amount)::bigint as amount
            from (values
              (v_cash,     v_cash_delta),
              (v_reserve,  -v_release),
              (v_counter,  case when o.side = 'buy' then v_gross else -v_gross end),
              (v_treasury, v_fee + v_tax)
            ) as e(account_id, amount)
           group by e.account_id
          having sum(e.amount) <> 0) x;
  if jsonb_array_length(v_entries) >= 2 then
    v_tx := public.ledger_post(
      case when p_system then 'bond_redemption'::public.ledger_tx_kind
           when o.side = 'buy' then 'trade_buy'::public.ledger_tx_kind
           else 'trade_sell'::public.ledger_tx_kind end,
      v_entries,
      case when o.side = 'buy' then 'Kauf ' else 'Verkauf ' end || s.ticker,
      'order', o.id, 'fill:' || v_trade_id::text, o.player_id,
      jsonb_build_object('quantity_e6', p_quantity, 'price_e4', p_price_e4, 'trade_id', v_trade_id));
  end if;

  -- XP: one trade XP per order, not below progression.xpSources.trade.minOrderValueCents,
  -- not for closing a position opened inside the wash-trade window
  if not p_system and not v_wash
     and v_gross >= public.cfg_num(v_prog, '{xpSources,trade,minOrderValueCents}', 10000) then
    v_xp := public.grant_xp(o.player_id, 'trade', public.cfg_num(v_prog, '{xpSources,trade,xp}', 10)::integer,
                            'trade:' || o.id::text, 'trade', v_trade_id);
  end if;

  select r.tick_seq into v_tick_seq from public.sim_runtime r where r.id;
  insert into public.trades (
    id, order_id, player_id, security_id, position_id, side, quantity_e6, price_e4, gross_cents, fee_cents,
    tax_cents, realized_pnl_cents, counterparty, ledger_transaction_id, tick_seq, is_wash_trade, xp_awarded, executed_at)
  values (
    v_trade_id, o.id, o.player_id, o.security_id, v_pos.id, o.side, p_quantity, p_price_e4, v_gross, v_fee,
    v_tax, case when o.side = 'sell' then v_pnl end,
    case when p_system then 'issuer'::public.trade_counterparty else 'market_maker'::public.trade_counterparty end,
    v_tx, v_tick_seq, v_wash, v_xp, v_now);

  if o.side = 'buy' then
    insert into public.position_lots (position_id, player_id, security_id, trade_id, quantity_initial_e6, quantity_open_e6, price_e4, acquired_at)
    values (v_pos.id, o.player_id, o.security_id, v_trade_id, p_quantity, p_quantity, p_price_e4, v_now);
    select coalesce(sum(public.value_cents(l.quantity_open_e6, l.price_e4)), 0)::bigint,
           coalesce(public.div_round_half_even(sum(l.quantity_open_e6::numeric * l.price_e4), sum(l.quantity_open_e6)), p_price_e4)
      into v_basis_new, v_avg_new
      from public.position_lots l where l.position_id = v_pos.id and l.quantity_open_e6 > 0;
    update public.positions
       set quantity_e6 = quantity_e6 + p_quantity, cost_basis_cents = v_basis_new, avg_entry_price_e4 = v_avg_new
     where id = v_pos.id;
  else
    select coalesce(public.div_round_half_even(sum(l.quantity_open_e6::numeric * l.price_e4), sum(l.quantity_open_e6)), 0)
      into v_avg_new
      from public.position_lots l where l.position_id = v_pos.id and l.quantity_open_e6 > 0;
    update public.positions
       set quantity_e6 = quantity_e6 - p_quantity,
           reserved_quantity_e6 = case when p_resting then reserved_quantity_e6 - p_quantity else reserved_quantity_e6 end,
           cost_basis_cents = v_basis_new,
           avg_entry_price_e4 = case when quantity_e6 - p_quantity = 0 then avg_entry_price_e4 else v_avg_new end,
           realized_pnl_cents = realized_pnl_cents + v_pnl,
           status = case when quantity_e6 - p_quantity = 0 then 'closed'::public.position_status else status end,
           closed_at = case when quantity_e6 - p_quantity = 0 then v_now else closed_at end
     where id = v_pos.id;

    v_year := coalesce((select q.game_year from public.current_game_quarter() q), 0);
    insert into public.player_tax_years as t (player_id, game_year, realized_gains_cents, realized_losses_cents, tax_paid_cents)
    values (o.player_id, v_year, greatest(v_pnl, 0), greatest(-v_pnl, 0), v_tax)
    on conflict (player_id, game_year) do update
      set realized_gains_cents  = t.realized_gains_cents + excluded.realized_gains_cents,
          realized_losses_cents = t.realized_losses_cents + excluded.realized_losses_cents,
          tax_paid_cents        = t.tax_paid_cents + excluded.tax_paid_cents,
          updated_at            = now();
  end if;

  update public.orders
     set filled_quantity_e6   = filled_quantity_e6 + p_quantity,
         avg_fill_price_e4    = public.div_round_half_even(
                                  coalesce(avg_fill_price_e4, 0)::numeric * filled_quantity_e6 + p_price_e4::numeric * p_quantity,
                                  filled_quantity_e6 + p_quantity),
         fee_cents            = fee_cents + v_fee,
         reserved_cents       = case when p_resting and side = 'buy' then 0 else reserved_cents end,
         reserved_quantity_e6 = case when p_resting and side = 'sell' then reserved_quantity_e6 - p_quantity else reserved_quantity_e6 end,
         status               = case when filled_quantity_e6 + p_quantity >= quantity_e6 then 'filled'::public.order_status
                                     else 'partially_filled'::public.order_status end,
         filled_at            = case when filled_quantity_e6 + p_quantity >= quantity_e6 then v_now else filled_at end
   where id = o.id;

  update public.security_quotes
     set day_volume_e6 = day_volume_e6 + p_quantity, day_turnover_cents = day_turnover_cents + v_gross
   where security_id = o.security_id;
  if not p_system then
    update public.security_sim_state
       set pending_player_flow_e6 = pending_player_flow_e6 + case when o.side = 'buy' then p_quantity else -p_quantity end,
           pending_player_volume_e6 = pending_player_volume_e6 + p_quantity
     where security_id = o.security_id;

    -- missions
    if v_first then
      perform public.mission_event(o.player_id, 'trade', 1, null);
      perform public.mission_event(o.player_id, case when o.side = 'buy' then 'buy' else 'sell' end, 1, null);
    end if;
    perform public.mission_event(o.player_id, 'trade_value', v_gross, null);
    perform public.mission_event(o.player_id, 'trading_day', 1, to_char(v_now at time zone 'Europe/Berlin', 'YYYY-MM-DD'));
    perform public.mission_event(o.player_id, 'distinct_security', 1, s.ticker);
    if o.side = 'buy' then
      perform public.mission_event(o.player_id, 'buy_value', v_gross, null);
      if s.kind = 'bond' then
        perform public.mission_event(o.player_id, 'bond_bought', 1, null);
      elsif s.sector_key is not null then
        perform public.mission_event(o.player_id, 'buy_sector', 1, s.sector_key);
        perform public.mission_event(o.player_id, 'sectors_bought', 1, s.sector_key);
      end if;
    elsif v_pnl > 0 then
      perform public.mission_event(o.player_id, 'realized_profit', v_pnl, null);
    end if;
  end if;

  return jsonb_build_object(
    'trade_id', v_trade_id, 'quantity_e6', p_quantity, 'price_e4', p_price_e4, 'gross_cents', v_gross,
    'fee_cents', v_fee, 'tax_cents', v_tax, 'realized_pnl_cents', case when o.side = 'sell' then v_pnl end,
    'xp_awarded', v_xp, 'wash_trade', v_wash);
end;
$$;

-- market_tick_at as in M2 with player-driven prices (ADR-056)
create or replace function public.market_tick_at(p_now timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_started   timestamptz := clock_timestamp();
  rt          public.sim_runtime;
  v_seq       bigint;
  v_time      jsonb := coalesce(public.config_jsonb('time'), '{}'::jsonb);
  v_trading   jsonb := coalesce(public.config_jsonb('trading'), '{}'::jsonb);
  v_ai        jsonb := coalesce(public.config_jsonb('aiInvestors'), '{}'::jsonb);
  v_sectors   jsonb := coalesce(public.config_jsonb('sectors'), '{}'::jsonb);
  v_bonds     jsonb := coalesce(public.config_jsonb('bonds'), '{}'::jsonb);
  v_regular   boolean;
  v_bell      timestamptz;
  v_qstart    timestamptz;
  v_ystart    timestamptz;
  v_new_day   boolean;
  v_filled    integer;
  v_policy    integer;
  v_epoch     constant timestamptz := '2000-01-01 00:00:00+00';
  v_local     timestamp := p_now at time zone 'Europe/Berlin';
  v_open_h    double precision;
  v_close_h   double precision;
  -- config scalars
  c_liq       double precision;
  c_noise     double precision;
  c_spreadf   double precision;
  c_depthfrac double precision;
  c_impact    double precision;
  c_exp       double precision;
  c_imm       double precision;
  c_hedge     double precision;
  c_maxret    double precision;
  c_minprice  bigint;
  c_minhalf   bigint;
  c_widen     double precision;
  c_decay     double precision;
  c_emaf      double precision;
  c_emas      double precision;
  c_vf_cap    double precision;
  c_vf_gap    double precision;
  c_vf_dead   double precision;
  c_mo_cap    double precision;
  c_mo_ts     double precision;
  c_rh_cap    double precision;
  c_rh_chase  double precision;
  c_rh_ts     double precision;
  c_mm_speed  double precision;
  c_basevol   double precision;
  c_nscale    double precision;
  c_qpy       double precision;
  c_qsec      double precision;
  -- ADR-056: player-driven prices
  v_pimp      jsonb := coalesce(public.config_jsonb('trading', '{playerImpact}'), '{}'::jsonb);
  v_pwt       jsonb := coalesce(public.config_jsonb('aiInvestors', '{playerWeight}'), '{}'::jsonb);
  c_actdecay  double precision;
  c_minw      double precision;
  c_maxprem   double precision;
  c_premscale double precision;
  c_bonddepth double precision;
  c_bondvol   double precision;
  v_pdepth    double precision;
  v_act       double precision;
  v_w         double precision;
  v_fva       double precision;
  v_held      double precision;
  -- per security
  r           record;
  v_price     double precision;
  v_depth     double precision;
  v_sent      double precision;
  v_flow      double precision;
  v_mm        double precision;
  v_ef        double precision;
  v_es        double precision;
  v_gap       double precision;
  v_trend     double precision;
  v_pv        double precision;
  v_pm        double precision;
  v_pr        double precision;
  v_pmm       double precision;
  v_ret       double precision;
  v_sigma     double precision;
  v_exact     double precision;
  v_new       bigint;
  v_half_bps  double precision;
  v_half      bigint;
  v_bid       bigint;
  v_ask       bigint;
  v_vol       bigint;
  v_dev       double precision;
  v_periods   double precision;
  v_years     double precision;
  v_yield     double precision;
  v_yield_out integer;
  v_mcap      bigint;
  v_imp_flow  double precision;
  -- bulk arrays
  a_id   uuid[] := '{}';
  a_p    bigint[] := '{}';
  a_b    bigint[] := '{}';
  a_a    bigint[] := '{}';
  a_v    bigint[] := '{}';
  a_s    double precision[] := '{}';
  a_ef   double precision[] := '{}';
  a_es   double precision[] := '{}';
  a_mm   double precision[] := '{}';
  a_dev  double precision[] := '{}';
  a_flow bigint[] := '{}';
  a_y    integer[] := '{}';
  a_mc   bigint[] := '{}';
  a_act  double precision[] := '{}';
  a_pvol bigint[] := '{}';
  -- index
  ix     record;
  v_cap  numeric;
  v_ixv  bigint;
  v_n    integer := 0;
begin
  if not pg_try_advisory_xact_lock(7311001) then
    return jsonb_build_object('skipped', 'busy');
  end if;
  select * into rt from public.sim_runtime where id;
  if rt.is_paused then
    return jsonb_build_object('skipped', 'paused', 'tick_seq', rt.tick_seq);
  end if;
  v_seq := rt.tick_seq + 1;

  -- session and calendar ----------------------------------------------------
  v_open_h  := public.cfg_num(v_time, '{marketOpenHour}', 8);
  v_close_h := public.cfg_num(v_time, '{marketCloseHour}', 22);
  v_regular := (extract(hour from v_local) + extract(minute from v_local) / 60.0) >= v_open_h
           and (extract(hour from v_local) + extract(minute from v_local) / 60.0) < v_close_h;
  v_bell    := public.trading_day_start(p_now);
  v_qstart  := public.quarter_bucket_start(p_now);
  v_ystart  := public.game_year_bucket_start(p_now);
  v_new_day := coalesce((rt.state ->> 'day_start')::timestamptz, '-infinity'::timestamptz) < v_bell;
  select cb.policy_rate_bps into v_policy from public.central_bank_state cb where cb.id;
  v_policy := coalesce(v_policy, public.config_double('centralBank', '{startRateBps}', 300)::integer);

  -- config ----------------------------------------------------------------------
  c_liq       := case when v_regular then 1 else public.cfg_num(v_time, '{afterHours,liquidityMultiplier}', 0.25) end;
  c_noise     := case when v_regular then 1 else public.cfg_num(v_time, '{afterHours,volatilityMultiplier}', 0.5) end;
  c_spreadf   := case when v_regular then 1 else public.cfg_num(v_time, '{afterHours,spreadMultiplier}', 3) end;
  c_depthfrac := public.cfg_num(v_trading, '{priceImpact,depthFreeFloatFraction}', 0.002);
  c_impact    := public.cfg_num(v_trading, '{priceImpact,impactBpsPerDepth}', 100) / 10000.0;
  c_exp       := public.cfg_num(v_trading, '{priceImpact,exponent}', 1);
  c_imm       := public.cfg_num(v_trading, '{priceImpact,immediateShare}', 0.5);
  c_hedge     := public.cfg_num(v_trading, '{priceImpact,marketMakerHedgeShare}', 0.5);
  c_maxret    := public.cfg_num(v_trading, '{maxTickReturnBps}', 300) / 10000.0;
  c_minprice  := greatest(1, public.cfg_num(v_trading, '{minPriceE4}', 1))::bigint;
  c_minhalf   := greatest(1, public.cfg_num(v_trading, '{spread,minHalfSpreadE4}', 1))::bigint;
  c_widen     := public.cfg_num(v_trading, '{spread,sentimentWideningBps}', 20);
  c_decay     := public.cfg_num(v_ai, '{sentimentDecayPerTick}', 0.0019);
  c_emaf      := public.cfg_num(v_ai, '{emaFastAlpha}', 0.15);
  c_emas      := public.cfg_num(v_ai, '{emaSlowAlpha}', 0.0165);
  c_vf_cap    := public.cfg_num(v_ai, '{archetypes,value_fund,capitalShare}', 0.3)
               * public.cfg_num(v_ai, '{archetypes,value_fund,reactionSpeed}', 0.0005) * c_liq;
  c_vf_gap    := public.cfg_num(v_ai, '{archetypes,value_fund,params,gapScale}', 0.5);
  c_vf_dead   := public.cfg_num(v_ai, '{archetypes,value_fund,params,deadBand}', 0.01);
  c_mo_cap    := public.cfg_num(v_ai, '{archetypes,momentum_trader,capitalShare}', 0.1)
               * public.cfg_num(v_ai, '{archetypes,momentum_trader,reactionSpeed}', 0.0002) * c_liq;
  c_mo_ts     := public.cfg_num(v_ai, '{archetypes,momentum_trader,params,trendScale}', 0.02);
  c_rh_cap    := public.cfg_num(v_ai, '{archetypes,retail_herd,capitalShare}', 0.1)
               * public.cfg_num(v_ai, '{archetypes,retail_herd,reactionSpeed}', 0.002) * c_liq;
  c_rh_chase  := public.cfg_num(v_ai, '{archetypes,retail_herd,params,chaseGain}', 0.1);
  c_rh_ts     := public.cfg_num(v_ai, '{archetypes,retail_herd,params,trendScale}', 0.02);
  c_mm_speed  := public.cfg_num(v_ai, '{archetypes,market_maker,reactionSpeed}', 0.005) * c_liq;
  c_basevol   := public.cfg_num(v_ai, '{baselineVolumeDepthFraction}', 0.02);
  -- Scale on tickNoiseBps for stocks (ADR-056: 0.45, livelier than the M1 target of 0.2).
  c_nscale    := public.cfg_num(v_ai, '{tickNoiseScale}', 0.45);
  c_qpy       := greatest(1, public.cfg_num(v_bonds, '{couponsPerGameYear}', 4));
  c_qsec      := public.cfg_num(v_time, '{quarterHours}', 6) * 3600;
  -- player activity: exponential decay per tick with activityHalfLifeHours
  c_actdecay  := power(0.5, public.cfg_num(v_time, '{tickSeconds}', 5)
                            / (greatest(public.cfg_num(v_pwt, '{activityHalfLifeHours}', 6), 0.001) * 3600));
  c_minw      := public.cfg_num(v_pwt, '{minAiWeight}', 0.15);
  c_maxprem   := public.cfg_num(v_pimp, '{maxHoldingsPremium}', 0.6);
  c_premscale := public.cfg_num(v_pimp, '{premiumScaleDepths}', 20);
  c_bonddepth := greatest(1, public.cfg_num(v_pimp, '{bondDepthCentsPer100Bps}', 5000000));
  c_bondvol   := public.cfg_num(v_bonds, '{volatilityMultiplier}', 3);

  -- 1. resting limit orders against the quote players currently see ----------
  v_filled := public.fill_resting_orders();

  -- 2./3. stocks and bonds ---------------------------------------------------------
  for r in
    select s.id, s.kind, s.sector_key, c.tier::text as tier, c.shares_outstanding,
           q.last_price_e4,
           st.fair_value_e4, st.sentiment, st.ema_fast, st.ema_slow, st.maker_inventory,
           st.pending_player_flow_e6, st.price_deviation, st.volatility, st.liquidity_shares, st.spread_bps,
           st.player_activity, st.pending_player_volume_e6, coalesce(h.held_e6, 0) as held_e6,
           b.coupon_bps, b.matures_at, b.face_value_cents
      from public.securities s
      join public.security_quotes q on q.security_id = s.id
      join public.security_sim_state st on st.security_id = s.id
      left join (select p.security_id, sum(p.quantity_e6) as held_e6
                   from public.positions p
                  where p.status = 'open' and p.side = 'long'
                  group by p.security_id) h on h.security_id = s.id
      left join public.companies c on c.id = s.company_id
      left join public.bonds b on b.security_id = s.id
     where s.status = 'listed' and s.kind in ('stock', 'bond')
  loop
    v_price := r.last_price_e4;
    v_flow  := r.pending_player_flow_e6 / 1000000.0;
    v_sent  := greatest(-1, least(1, coalesce(r.sentiment, 0) * (1 - c_decay)));
    v_ef    := coalesce(r.ema_fast, v_price);
    v_es    := coalesce(r.ema_slow, v_price);
    v_mm    := coalesce(r.maker_inventory, 0) - v_flow;
    v_dev   := coalesce(r.price_deviation, 0);
    v_yield_out := null;
    v_mcap  := null;
    -- player activity (cents): decayed old value plus this tick's gross player volume at the last price
    v_act   := coalesce(r.player_activity, 0) * c_actdecay
             + abs(coalesce(r.pending_player_volume_e6, 0)) / 1000000.0 * v_price / 100.0;

    if r.kind = 'stock' and r.shares_outstanding is not null then
      v_depth := greatest(1, r.shares_outstanding * c_depthfrac * c_liq);
      v_pdepth := greatest(1, public.cfg_num(v_pimp, array['depthCentsPer100Bps', coalesce(r.tier, 'midcap')], 2500000));
      -- AI traders fade with player activity: w = max(minAiWeight, R / (R + activity))
      v_w := greatest(c_minw, public.cfg_num(v_pwt, array['referenceActivityCents', coalesce(r.tier, 'midcap')], 25000000)
                              / (public.cfg_num(v_pwt, array['referenceActivityCents', coalesce(r.tier, 'midcap')], 25000000)
                                 + greatest(v_act, 0)));
      -- value fund: anchor = fair value x (1 + maxPremium x tanh(player held value / (scale x depth)))
      v_held := greatest(0, r.held_e6 / 1000000.0 * v_price / 100.0);
      v_fva := r.fair_value_e4 * (1 + c_maxprem * tanh(v_held / (c_premscale * v_pdepth)));
      v_gap := ln(v_fva / v_price);
      if abs(v_gap) <= c_vf_dead then
        v_pv := 0;
      else
        v_pv := r.shares_outstanding * c_vf_cap
              * greatest(-1, least(1, (v_gap - sign(v_gap) * c_vf_dead) / c_vf_gap));
      end if;
      v_trend := case when v_es > 0 then v_ef / v_es - 1 else 0 end;
      v_pm  := r.shares_outstanding * c_mo_cap * tanh(v_trend / c_mo_ts) * v_w;
      v_pr  := r.shares_outstanding * c_rh_cap * greatest(-1, least(1, v_sent + c_rh_chase * tanh(v_trend / c_rh_ts))) * v_w;
      v_pmm := -v_mm * c_mm_speed * c_hedge;
      -- AI order flow through the depth model; player orders in euros (fully immediate):
      -- 0.01 x net value / depthCentsPer100Bps / liquidity
      v_ret := sign(v_pv + v_pm + v_pr + v_pmm) * c_impact * power(abs(v_pv + v_pm + v_pr + v_pmm) / v_depth, c_exp)
             + 0.01 * (v_flow * v_price / 100.0) / v_pdepth / c_liq;
      v_sigma := v_w * public.cfg_num(v_ai, array['tickNoiseBps', coalesce(r.tier, 'midcap')], 15) / 10000.0
               * public.cfg_num(v_sectors, array[coalesce(r.sector_key, ''), 'volatilityMultiplier'], 1)
               * c_noise * c_nscale;
      v_ret := greatest(-c_maxret, least(c_maxret, v_ret + v_sigma * public.gauss_random()));
      v_exact := v_price * exp(v_ret);
      v_new := floor(v_exact)::bigint + case when random() < v_exact - floor(v_exact) then 1 else 0 end;
      v_new := greatest(c_minprice, v_new);
      v_mm  := v_mm * (1 - c_mm_speed);
      v_half_bps := (public.cfg_num(v_trading, array['spread', 'halfSpreadBps', coalesce(r.tier, 'midcap')], 15)
                     + c_widen * least(1, abs(v_sent))) * c_spreadf;
      v_vol := round((abs(v_pv) + abs(v_pm) + abs(v_pr) + abs(v_pmm) + v_depth * c_basevol * (0.5 + random())) * 1000000)::bigint;
      v_mcap := public.div_round_half_even(r.shares_outstanding::numeric * v_new, 100);
    elsif r.kind = 'bond' and r.matures_at is not null then
      v_depth   := greatest(1, coalesce(r.liquidity_shares, 100000) * c_liq);
      v_periods := extract(epoch from (r.matures_at - p_now)) / c_qsec;
      v_years   := greatest(v_periods / c_qpy, 0);
      v_yield   := public.bond_yield_bps(v_policy, v_years, v_bonds);
      -- player orders in euros: 0.01 x net value / bondDepthCentsPer100Bps / liquidity
      v_imp_flow := 0.01 * (v_flow * v_price / 100.0) / c_bonddepth / c_liq;
      v_dev := v_dev * (1 - c_decay) + coalesce(r.volatility, 0) * c_bondvol * c_noise * public.gauss_random() + v_imp_flow;
      if v_periods > 0 then
        v_new := greatest(c_minprice, round(public.bond_clean_price(r.coupon_bps, v_yield, v_periods, c_qpy)
                                            * exp(v_dev) * r.face_value_cents * 100)::bigint);
        v_yield_out := round(v_yield - v_dev * 10000 / greatest(v_years, 0.25))::integer;
      else
        v_new := r.face_value_cents * 100;
        v_yield_out := 0;
      end if;
      v_half_bps := coalesce(r.spread_bps, 10) / 2.0 * c_spreadf;
      v_vol := round(v_depth * c_basevol * (0.5 + random()) * 1000000)::bigint;
    else
      continue;
    end if;

    v_ef := v_ef + c_emaf * (v_new - v_ef);
    v_es := v_es + c_emas * (v_new - v_es);
    v_half := greatest(c_minhalf, round(v_new * v_half_bps / 10000.0)::bigint);
    v_bid := greatest(c_minprice, v_new - v_half);
    v_ask := v_new + v_half;
    if v_ask <= v_bid then
      v_ask := v_bid + 1;
    end if;

    a_id := a_id || r.id;      a_p := a_p || v_new;        a_b := a_b || v_bid;     a_a := a_a || v_ask;
    a_v := a_v || v_vol;       a_s := a_s || v_sent;       a_ef := a_ef || v_ef;    a_es := a_es || v_es;
    a_mm := a_mm || v_mm;      a_dev := a_dev || v_dev;    a_flow := a_flow || r.pending_player_flow_e6;
    a_y := a_y || v_yield_out; a_mc := a_mc || v_mcap;
    a_act := a_act || v_act;   a_pvol := a_pvol || coalesce(r.pending_player_volume_e6, 0);
    v_n := v_n + 1;
  end loop;

  update public.security_sim_state st
     set sentiment = u.s, ema_fast = u.ef, ema_slow = u.es, maker_inventory = u.mm,
         price_deviation = u.dev, pending_player_flow_e6 = st.pending_player_flow_e6 - u.flow,
         player_activity = u.act, pending_player_volume_e6 = st.pending_player_volume_e6 - u.pvol
    from unnest(a_id, a_s, a_ef, a_es, a_mm, a_dev, a_flow, a_act, a_pvol) as u(id, s, ef, es, mm, dev, flow, act, pvol)
   where st.security_id = u.id;

  update public.security_quotes q
     set last_price_e4 = u.p,
         bid_e4 = u.b,
         ask_e4 = u.a,
         prev_close_e4 = case when v_new_day then q.last_price_e4 else coalesce(q.prev_close_e4, q.last_price_e4) end,
         day_open_e4 = case when v_new_day then u.p else coalesce(q.day_open_e4, u.p) end,
         day_high_e4 = case when v_new_day then u.p else greatest(coalesce(q.day_high_e4, u.p), u.p) end,
         day_low_e4 = case when v_new_day then u.p else least(coalesce(q.day_low_e4, u.p), u.p) end,
         day_volume_e6 = case when v_new_day then u.v else q.day_volume_e6 + u.v end,
         day_turnover_cents = case when v_new_day then 0 else q.day_turnover_cents end,
         change_bps = greatest(-1000000, least(1000000, round(
                        (u.p - case when v_new_day then q.last_price_e4 else coalesce(q.prev_close_e4, q.last_price_e4) end) * 10000.0
                        / greatest(1, case when v_new_day then q.last_price_e4 else coalesce(q.prev_close_e4, q.last_price_e4) end))))::integer,
         market_cap_cents = coalesce(u.mc, q.market_cap_cents),
         yield_bps = coalesce(u.y, q.yield_bps),
         tick_seq = v_seq,
         updated_at = p_now
    from unnest(a_id, a_p, a_b, a_a, a_v, a_y, a_mc) as u(id, p, b, a, v, y, mc)
   where q.security_id = u.id;

  -- 4. indices ---------------------------------------------------------------------
  for ix in
    select i.security_id, i.divisor
      from public.indices i join public.securities s on s.id = i.security_id
     where s.status = 'listed'
  loop
    select sum(c.shares_outstanding::numeric * q.last_price_e4) / 100
      into v_cap
      from public.index_memberships m
      join public.securities s on s.id = m.member_security_id
      join public.companies c on c.id = s.company_id
      join public.security_quotes q on q.security_id = s.id
     where m.index_security_id = ix.security_id and m.left_at is null;
    if v_cap is null or ix.divisor <= 0 then
      continue;
    end if;
    v_ixv := greatest(1, round(v_cap / ix.divisor::numeric))::bigint;
    update public.security_quotes q
       set last_price_e4 = v_ixv,
           prev_close_e4 = case when v_new_day then q.last_price_e4 else coalesce(q.prev_close_e4, q.last_price_e4) end,
           day_open_e4 = case when v_new_day then v_ixv else coalesce(q.day_open_e4, v_ixv) end,
           day_high_e4 = case when v_new_day then v_ixv else greatest(coalesce(q.day_high_e4, v_ixv), v_ixv) end,
           day_low_e4 = case when v_new_day then v_ixv else least(coalesce(q.day_low_e4, v_ixv), v_ixv) end,
           change_bps = round((v_ixv - case when v_new_day then q.last_price_e4 else coalesce(q.prev_close_e4, q.last_price_e4) end) * 10000.0
                        / greatest(1, case when v_new_day then q.last_price_e4 else coalesce(q.prev_close_e4, q.last_price_e4) end))::integer,
           market_cap_cents = round(v_cap)::bigint,
           tick_seq = v_seq,
           updated_at = p_now
     where q.security_id = ix.security_id;
    a_id := a_id || ix.security_id;
    a_p  := a_p || v_ixv;
    a_v  := a_v || 0::bigint;
  end loop;

  -- 5. ticks and candles --------------------------------------------------------------
  insert into public.price_ticks (security_id, ts, tick_seq, price_e4, volume_e6)
  select u.id, p_now, v_seq, u.p, u.v from unnest(a_id, a_p, a_v) as u(id, p, v)
  on conflict do nothing;

  insert into public.candles as c (security_id, interval, bucket_start, open_e4, high_e4, low_e4, close_e4, volume_e6, tick_count)
  select u.id, iv.i, iv.b, u.p, u.p, u.p, u.p, u.v, 1
    from unnest(a_id, a_p, a_v) as u(id, p, v)
   cross join (values
     ('1m'::public.candle_interval, date_bin('1 minute', p_now, v_epoch)),
     ('5m'::public.candle_interval, date_bin('5 minutes', p_now, v_epoch)),
     ('1h'::public.candle_interval, date_bin('1 hour', p_now, v_epoch)),
     ('1q'::public.candle_interval, v_qstart),
     ('1y'::public.candle_interval, v_ystart)) as iv(i, b)
  on conflict (security_id, interval, bucket_start) do update
     set high_e4 = greatest(c.high_e4, excluded.high_e4),
         low_e4 = least(c.low_e4, excluded.low_e4),
         close_e4 = excluded.close_e4,
         volume_e6 = c.volume_e6 + excluded.volume_e6,
         tick_count = c.tick_count + 1;

  -- runtime, public market status, tick log
  update public.sim_runtime
     set tick_seq = v_seq, last_tick_at = p_now,
         state = case when v_new_day then state || jsonb_build_object('day_start', v_bell) else state end
   where id;
  update public.market_status
     set phase = case when v_regular then 'open'::public.market_phase else 'after_hours'::public.market_phase end,
         phase_changed_at = case when phase is distinct from (case when v_regular then 'open'::public.market_phase
                                                                   else 'after_hours'::public.market_phase end)
                                 then p_now else phase_changed_at end,
         next_open_at = case when v_local < v_local::date + make_interval(secs => v_open_h * 3600)
                             then (v_local::date + make_interval(secs => v_open_h * 3600)) at time zone 'Europe/Berlin'
                             else (v_local::date + 1 + make_interval(secs => v_open_h * 3600)) at time zone 'Europe/Berlin' end,
         next_close_at = case when v_local < v_local::date + make_interval(secs => v_close_h * 3600)
                              then (v_local::date + make_interval(secs => v_close_h * 3600)) at time zone 'Europe/Berlin'
                              else (v_local::date + 1 + make_interval(secs => v_close_h * 3600)) at time zone 'Europe/Berlin' end,
         tick_seq = v_seq, last_tick_at = p_now, is_halted = false, halt_reason = null
   where id;
  insert into public.sim_tick_log (tick_seq, started_at, duration_ms, securities_updated, orders_filled)
  values (v_seq, v_started, round(extract(epoch from (clock_timestamp() - v_started)) * 1000)::integer, v_n, v_filled)
  on conflict (tick_seq) do nothing;

  return jsonb_build_object(
    'tick_seq', v_seq, 'session', case when v_regular then 'regular' else 'after_hours' end,
    'securities', v_n, 'orders_filled', v_filled, 'new_day', v_new_day,
    'duration_ms', round(extract(epoch from (clock_timestamp() - v_started)) * 1000, 2));
end;
$$;

do $$
declare
  f text;
begin
  foreach f in array array['public.execute_fill(uuid, bigint, bigint, boolean, boolean)', 'public.market_tick_at(timestamptz)'] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
end;
$$;

-- ===== supabase/migrations/20261114000300_m3c_companies_schema.sql =====
-- =============================================================================
-- NEXA · M3c · 0300 · Player companies: schema and error keys (ADR-057,
--                     docs/PLAYER_COMPANIES.md)
-- =============================================================================
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- Error keys (M3c: NX047..NX052)
-- ---------------------------------------------------------------------------
create or replace function public.api_error(p_key text)
returns void
language plpgsql
set search_path = ''
as $$
declare
  v_code text;
begin
  v_code := case p_key
    when 'insufficient_funds'          then 'NX001'
    when 'rate_limited'                then 'NX004'
    when 'forbidden'                   then 'NX006'
    when 'invalid_quantity'            then 'NX007'
    when 'invalid_price'               then 'NX007'
    when 'invalid_argument'            then 'NX007'
    when 'invalid_interval'            then 'NX007'
    when 'not_authenticated'           then 'NX010'
    when 'unknown_security'            then 'NX011'
    when 'not_tradable'                then 'NX012'
    when 'insufficient_position'       then 'NX013'
    when 'order_not_found'             then 'NX014'
    when 'order_not_open'              then 'NX015'
    when 'market_paused'               then 'NX016'
    when 'nothing_to_claim'            then 'NX017'
    when 'locked'                      then 'NX018'
    when 'name_too_short'              then 'NX019'
    when 'name_too_long'               then 'NX019'
    when 'name_invalid_chars'          then 'NX019'
    when 'name_profanity'              then 'NX019'
    when 'name_reserved'               then 'NX019'
    when 'name_taken'                  then 'NX019'
    when 'name_change_too_soon'        then 'NX020'
    when 'order_too_small'             then 'NX021'
    when 'market_illiquid'             then 'NX022'
    when 'mission_not_found'           then 'NX023'
    when 'mission_not_completed'       then 'NX024'
    when 'mission_already_claimed'     then 'NX025'
    when 'avatar_unknown'              then 'NX026'
    when 'avatar_locked'               then 'NX027'
    when 'daily_reward_claimed'        then 'NX028'
    when 'skill_unknown'               then 'NX029'
    when 'skill_learned'               then 'NX030'
    when 'skill_locked'                then 'NX031'
    when 'skill_points_insufficient'   then 'NX032'
    when 'job_not_found'               then 'NX033'
    when 'job_level_too_low'           then 'NX034'
    when 'job_skills_missing'          then 'NX035'
    when 'application_limit'           then 'NX036'
    when 'application_exists'          then 'NX037'
    when 'application_not_found'       then 'NX038'
    when 'application_not_offered'     then 'NX039'
    when 'offer_expired'               then 'NX040'
    when 'job_active_exists'           then 'NX041'
    when 'no_active_job'               then 'NX042'
    when 'raise_too_soon'              then 'NX043'
    when 'raise_too_high'              then 'NX044'
    when 'player_not_found'            then 'NX045'
    when 'employer_only'               then 'NX046'
    when 'company_exists'              then 'NX047'
    when 'company_not_found'           then 'NX048'
    when 'company_level_too_low'       then 'NX049'
    when 'owns_company'                then 'NX050'
    when 'employee_limit'              then 'NX051'
    when 'company_upgrade_unavailable' then 'NX052'
    else 'NX007'
  end;
  raise exception using errcode = v_code, message = p_key;
end;
$$;

-- ---------------------------------------------------------------------------
-- Player companies (one per founder) and their quarterly reports
-- ---------------------------------------------------------------------------
create table if not exists public.player_companies (
  company_id                  uuid primary key references public.companies (id) on delete cascade,
  founder_id                  uuid not null unique references public.profiles (id) on delete cascade,
  idea                        text not null check (char_length(idea) between 1 and 120),
  tier                        text not null default 'garage' check (tier in ('garage', 'small_business')),
  potential_annual_cents      bigint not null check (potential_annual_cents > 0),
  awareness                   double precision not null check (awareness between 0 and 1),
  quality                     double precision not null check (quality between 0 and 1),
  quarters_active             integer not null default 0 check (quarters_active >= 0),
  marketing_cents_per_quarter bigint not null default 0 check (marketing_cents_per_quarter >= 0),
  ai_workers                  integer not null default 0 check (ai_workers >= 0),
  unpaid_cents                bigint not null default 0 check (unpaid_cents >= 0),
  distress                    boolean not null default false,
  last_closed_quarter_id      bigint references public.game_quarters (id),
  request_id                  uuid,
  created_at                  timestamptz not null default now(),
  updated_at                  timestamptz not null default now()
);
alter table public.player_companies enable row level security;
create index if not exists player_companies_last_quarter_idx on public.player_companies (last_closed_quarter_id);
comment on table public.player_companies is 'Player companies (garage startup, small business; ADR-057). potential_annual_cents is hidden from everyone (no column grant).';
comment on column public.player_companies.potential_annual_cents is 'Hidden market size of the niche (Pareto draw at founding). Never readable by players.';

create table if not exists public.player_company_reports (
  company_id             uuid not null references public.player_companies (company_id) on delete cascade,
  game_quarter_id        bigint not null references public.game_quarters (id),
  label                  text not null,
  demand_cents           bigint not null,
  capacity_cents         bigint not null,
  revenue_cents          bigint not null,
  cogs_cents             bigint not null,
  fixed_cents            bigint not null,
  ai_worker_cents        bigint not null,
  marketing_cents        bigint not null,
  wages_cents            bigint not null default 0,
  operating_profit_cents bigint not null,
  utilization_bps        integer not null,
  paid_costs_cents       bigint not null default 0,
  unpaid_added_cents     bigint not null default 0,
  awareness_bps          integer not null,
  quality_bps            integer not null,
  team_productivity_bps  integer not null,
  team_sector_score      integer not null,
  created_at             timestamptz not null default now(),
  primary key (company_id, game_quarter_id)
);
alter table public.player_company_reports enable row level security;
create index if not exists player_company_reports_quarter_idx on public.player_company_reports (game_quarter_id);
comment on table public.player_company_reports is 'Quarterly report of a player company (closeStartupQuarter). Wages are the M2b salary payouts of the quarter.';

do $$
begin
  revoke all on public.player_companies from public, anon, authenticated;
  grant select (company_id, founder_id, idea, tier, awareness, quality, quarters_active, marketing_cents_per_quarter,
                ai_workers, unpaid_cents, distress, last_closed_quarter_id, created_at, updated_at)
    on public.player_companies to authenticated;
  grant all on public.player_companies to service_role;
  drop policy if exists "owner read" on public.player_companies;
  create policy "owner read" on public.player_companies for select to authenticated
    using (founder_id = (select auth.uid()));

  revoke all on public.player_company_reports from public, anon, authenticated;
  grant select on public.player_company_reports to authenticated;
  grant all on public.player_company_reports to service_role;
  drop policy if exists "owner read" on public.player_company_reports;
  create policy "owner read" on public.player_company_reports for select to authenticated
    using (exists (select 1 from public.player_companies pc
                    where pc.company_id = player_company_reports.company_id and pc.founder_id = (select auth.uid())));

  if not exists (select 1 from pg_trigger where tgname = 'set_updated_at' and tgrelid = 'public.player_companies'::regclass) then
    create trigger set_updated_at before update on public.player_companies for each row execute function public.set_updated_at();
  end if;
end;
$$;

-- ===== supabase/migrations/20261114000400_m3c_companies.sql =====
-- =============================================================================
-- NEXA · M3c · 0400 · Player companies: founding, quarter close, employer side
--                     (ADR-057, docs/PLAYER_COMPANIES.md)
-- =============================================================================
-- Mirrors src/lib/sim/startup.ts (closeStartupQuarter, startupValueCents,
-- potentialFromUniform, potentialEstimate, qualityTarget, marketingGain,
-- capacityCents) and src/lib/sim/skills.ts (productivityBps, matchScore).
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- Tier values: garage from startups.garage, small business from company.tiers
-- ---------------------------------------------------------------------------
create or replace function public.company_tier_cfg(p_tier text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select case p_tier
    when 'garage' then jsonb_build_object(
      'minLevel', greatest(public.config_double('startups', '{garage,minLevel}', 3)::integer, public.unlock_level('found_garage')),
      'foundingCostCents', public.config_bigint('startups', '{garage,foundingCostCents}', 250000),
      'fixedCostCentsPerQuarter', public.config_bigint('startups', '{garage,fixedCostCentsPerQuarter}', 15000),
      'maxEmployees', public.config_double('startups', '{garage,maxEmployees}', 2)::integer)
    when 'small_business' then (
      select jsonb_build_object(
        'minLevel', greatest(coalesce((t ->> 'minLevel')::integer, 10), public.unlock_level('found_small_business')),
        'foundingCostCents', coalesce((t ->> 'foundingCostCents')::bigint, 1500000),
        'fixedCostCentsPerQuarter', coalesce((t ->> 'fixedCostCentsPerQuarter')::bigint, 200000),
        'maxEmployees', coalesce((t ->> 'maxEmployees')::integer, 5))
        from (select coalesce((select x from jsonb_array_elements(coalesce(public.config_jsonb('company', '{tiers}'), '[]'::jsonb)) x
                                where x ->> 'id' = 'small_business' limit 1), '{}'::jsonb) as t) s)
  end;
$$;

-- Hidden market size from a uniform u in (0, 1]: Pareto, capped (potentialFromUniform).
create or replace function public.startup_potential_from_uniform(p_u double precision)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select least(public.config_double('startups', '{potential,maxAnnualCents}', 200000000000),
               round(public.config_double('startups', '{potential,minAnnualCents}', 100000)
                     * power(least(1, greatest(coalesce(p_u, 1), 1e-12)),
                             -1 / public.config_double('startups', '{potential,paretoAlpha}', 0.57))))::bigint;
$$;

create or replace function public.company_cash_account(p_company uuid)
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select a.id from public.ledger_accounts a where a.owner_company_id = p_company and a.kind = 'company_cash';
$$;

-- Company value: cash - unpaid + max(0, last quarter profit) x 4 x sector P/E x valuationPeDiscount (startupValueCents).
create or replace function public.company_value_cents(p_company uuid)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select greatest(0,
           coalesce((select a.balance_cents from public.ledger_accounts a where a.owner_company_id = pc.company_id and a.kind = 'company_cash'), 0)
           - pc.unpaid_cents
           + round(4 * greatest(0, coalesce((select r.operating_profit_cents from public.player_company_reports r
                                               join public.game_quarters gq on gq.id = r.game_quarter_id
                                              where r.company_id = pc.company_id order by gq.ends_at desc limit 1), 0))
                   * public.config_double('sectors', array[c.sector_key, 'peRatio'], 15)
                   * public.config_double('startups', '{valuationPeDiscount}', 0.5))::bigint)::bigint
    from public.player_companies pc join public.companies c on c.id = pc.company_id
   where pc.company_id = p_company;
$$;

-- Value of the company a player founded (0 without one).
create or replace function public.player_company_value_cents(p_player uuid)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select public.company_value_cents(pc.company_id) from public.player_companies pc where pc.founder_id = p_player), 0)::bigint;
$$;

-- The team of a player company: founder (matchScore over the sector's first two branches),
-- active player employees (their job productivity), AI workers (10 000 bps each).
create or replace function public.player_company_team(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  pc       public.player_companies;
  v_sector text;
  v_list   jsonb;
  v_req    jsonb;
  v_fs     jsonb;
  v_found  integer;
  v_prod   bigint;
  v_score  integer;
  v_emp    integer := 0;
  v_s      jsonb;
  r        record;
begin
  select * into pc from public.player_companies where company_id = p_company;
  if pc.company_id is null then
    return null;
  end if;
  select c.sector_key into v_sector from public.companies c where c.id = p_company;
  v_list := coalesce(public.config_jsonb('jobs', array['sectorBranches', v_sector]), '[]'::jsonb);
  select coalesce(jsonb_agg(jsonb_build_object('branch', b, 'min_score', 0) order by o), '[]'::jsonb) into v_req
    from jsonb_array_elements_text(v_list) with ordinality x(b, o) where o <= 2;
  v_fs := public.player_branch_scores(pc.founder_id);
  v_found := public.job_productivity_bps(public.job_match_score(v_fs, v_req));
  select coalesce(sum(coalesce((v_fs ->> b)::integer, 0)), 0) into v_score from jsonb_array_elements_text(v_list) b;
  v_prod := v_found;
  for r in select j.player_id, j.required from public.player_jobs j where j.company_id = p_company and j.status = 'active' loop
    v_s := public.player_branch_scores(r.player_id);
    v_prod := v_prod + public.job_productivity_bps(public.job_match_score(v_s, r.required));
    v_score := v_score + (select coalesce(sum(coalesce((v_s ->> b)::integer, 0)), 0) from jsonb_array_elements_text(v_list) b);
    v_emp := v_emp + 1;
  end loop;
  v_prod := v_prod + pc.ai_workers * 10000;
  return jsonb_build_object(
    'founder_productivity_bps', v_found,
    'team_productivity_bps', v_prod,
    'employees', v_emp,
    'team_sector_score', v_score,
    'capacity_cents', round(v_prod / 10000.0
                            * public.config_double('startups', array['capacityCentsPerProductivity', v_sector], 250000))::bigint);
end;
$$;

-- Uniform number in [0, 1) derived from a text (estimate seeds per company and quarter).
create or replace function public.uniform_from_text(p_text text)
returns double precision
language sql
immutable
set search_path = ''
as $$
  select (hashtext(p_text)::bigint + 2147483648) / 4294967296.0;
$$;

create or replace function public.game_quarter_label(p_quarter_id bigint)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select 'J' || gq.game_year || ' Q' || gq.quarter from public.game_quarters gq where gq.id = p_quarter_id;
$$;

-- COMPANY shape (get_my_company and every company RPC)
create or replace function public.company_state(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  pc       public.player_companies;
  c        public.companies;
  v_team   jsonb;
  v_tier   jsonb;
  v_sb     jsonb;
  v_level  integer;
  v_cash   bigint;
  v_spread double precision;
  v_last   jsonb;
  v_hist   jsonb;
  v_cost   bigint;
begin
  select * into pc from public.player_companies where company_id = p_company;
  if pc.company_id is null then
    return null;
  end if;
  select * into c from public.companies where id = p_company;
  v_team := public.player_company_team(p_company);
  v_tier := public.company_tier_cfg(pc.tier);
  v_sb := public.company_tier_cfg('small_business');
  select p.level into v_level from public.profiles p where p.id = pc.founder_id;
  v_cash := coalesce((select a.balance_cents from public.ledger_accounts a where a.owner_company_id = p_company and a.kind = 'company_cash'), 0);
  v_spread := public.config_double('startups', '{estimate,initialSpread}', 2.3)
            * power(public.config_double('startups', '{estimate,decayPerQuarter}', 0.85), pc.quarters_active);
  select jsonb_build_object(
           'label', r.label, 'demand_cents', r.demand_cents, 'capacity_cents', r.capacity_cents,
           'revenue_cents', r.revenue_cents, 'cogs_cents', r.cogs_cents, 'fixed_cents', r.fixed_cents,
           'ai_worker_cents', r.ai_worker_cents, 'marketing_cents', r.marketing_cents, 'wages_cents', r.wages_cents,
           'operating_profit_cents', r.operating_profit_cents, 'utilization_bps', r.utilization_bps)
    into v_last
    from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
   where r.company_id = p_company order by gq.ends_at desc limit 1;
  select coalesce(jsonb_agg(jsonb_build_object('label', h.label, 'revenue_cents', h.revenue_cents,
                                               'profit_cents', h.operating_profit_cents) order by h.ends_at), '[]'::jsonb)
    into v_hist
    from (select r.label, r.revenue_cents, r.operating_profit_cents, gq.ends_at
            from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
           where r.company_id = p_company order by gq.ends_at desc limit 12) h;
  if pc.tier = 'garage' then
    v_cost := greatest(0, (v_sb ->> 'foundingCostCents')::bigint
                          - round((v_tier ->> 'foundingCostCents')::bigint
                                  * public.config_double('startups', '{upgradeCreditShare}', 1))::bigint);
  end if;
  return jsonb_build_object(
    'id', c.id,
    'name', c.name,
    'idea', pc.idea,
    'sector', c.sector_key,
    'color', c.brand_color,
    'tier', pc.tier,
    'founded_at', c.founded_at,
    'cash_cents', v_cash,
    'value_cents', public.company_value_cents(p_company),
    'unpaid_cents', pc.unpaid_cents,
    'distress', pc.distress,
    'awareness_bps', round(pc.awareness * 10000)::integer,
    'quality_bps', round(pc.quality * 10000)::integer,
    'quarters_active', pc.quarters_active,
    'estimate_low_cents', round(pc.potential_annual_cents
                                * exp(-v_spread * (0.3 + 0.7 * public.uniform_from_text(pc.company_id::text || ':' || pc.quarters_active || ':low'))))::bigint,
    'estimate_high_cents', round(pc.potential_annual_cents
                                 * exp(v_spread * (0.3 + 0.7 * public.uniform_from_text(pc.company_id::text || ':' || pc.quarters_active || ':high'))))::bigint,
    'marketing_cents_per_quarter', pc.marketing_cents_per_quarter,
    'ai_workers', pc.ai_workers,
    'ai_worker_cost_cents', public.config_bigint('startups', '{aiWorkerCostCentsPerQuarter}', 70000),
    'max_employees', (v_tier ->> 'maxEmployees')::integer,
    'employees', (v_team ->> 'employees')::integer,
    'open_postings', (select count(*) from public.job_postings jp where jp.company_id = p_company and jp.status = 'open')::integer,
    'pending_applications', (select count(*) from public.job_applications a join public.job_postings jp on jp.id = a.posting_id
                              where jp.company_id = p_company and a.status = 'pending')::integer,
    'founder_productivity_bps', (v_team ->> 'founder_productivity_bps')::integer,
    'team_productivity_bps', (v_team ->> 'team_productivity_bps')::integer,
    'capacity_cents', (v_team ->> 'capacity_cents')::bigint,
    'next_quarter_at', coalesce((public.current_game_quarter()).ends_at, public.game_now()),
    'can_upgrade', pc.tier = 'garage' and coalesce(v_level, 1) >= (v_sb ->> 'minLevel')::integer,
    'upgrade_cost_cents', v_cost,
    'last_quarter', v_last,
    'history', v_hist);
end;
$$;

-- ---------------------------------------------------------------------------
-- Quarter close of one player company (closeStartupQuarter), idempotent per quarter
-- ---------------------------------------------------------------------------
create or replace function public.player_company_close_quarter(p_company uuid, p_quarter_id bigint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  pc        public.player_companies;
  c         public.companies;
  q         public.game_quarters;
  v_su      jsonb := coalesce(public.config_jsonb('startups'), '{}'::jsonb);
  v_team    jsonb;
  v_tier    jsonb;
  v_qpot    double precision;
  v_target  double precision;
  v_quality double precision;
  v_mk      bigint;
  v_half    double precision;
  v_gain    double precision := 0;
  v_aw      double precision;
  v_demand  double precision;
  v_cap     double precision;
  v_rev     double precision;
  v_rev_c   bigint;
  v_cogs    bigint;
  v_fixed   bigint;
  v_aiw     bigint;
  v_op      bigint;
  v_costs   bigint;
  v_pay     bigint := 0;
  v_unpaid  bigint := 0;
  v_settle  bigint := 0;
  v_cash    bigint;
  v_acc     uuid;
  v_hh      uuid;
  v_wages   bigint;
  v_xp      integer := 0;
  v_ai      integer;
  k         text;
begin
  select * into pc from public.player_companies where company_id = p_company for update;
  select * into q from public.game_quarters where id = p_quarter_id;
  if pc.company_id is null or q.id is null then
    return null;
  end if;
  if exists (select 1 from public.player_company_reports r where r.company_id = p_company and r.game_quarter_id = p_quarter_id) then
    return jsonb_build_object('company_id', p_company, 'skipped', 'already_closed');
  end if;
  select * into c from public.companies where id = p_company;
  v_team := public.player_company_team(p_company);
  v_tier := public.company_tier_cfg(pc.tier);
  k := 'pcq:' || p_company::text || ':' || p_quarter_id::text;

  -- quality towards what the team can do, awareness by word of mouth and marketing
  v_qpot := pc.potential_annual_cents / 4.0;
  v_target := public.cfg_num(v_su, '{quality,base}', 0.25)
            + (1 - public.cfg_num(v_su, '{quality,base}', 0.25))
              * (greatest(0, (v_team ->> 'team_sector_score')::double precision)
                 / (greatest(0, (v_team ->> 'team_sector_score')::double precision) + public.cfg_num(v_su, '{quality,halfSaturationScore}', 20)));
  v_quality := least(1, greatest(0, pc.quality + public.cfg_num(v_su, '{quality,adjustPerQuarter}', 0.35) * (v_target - pc.quality)));
  v_mk := pc.marketing_cents_per_quarter;
  if v_mk > 0 then
    v_half := greatest(public.cfg_num(v_su, '{awareness,marketingMinHalfSaturationCents}', 50000),
                       pc.potential_annual_cents / 4.0 * public.cfg_num(v_su, '{awareness,marketingHalfSaturationShare}', 0.1));
    v_gain := public.cfg_num(v_su, '{awareness,marketingMaxGain}', 0.12) * v_mk / (v_mk + v_half);
  end if;
  v_aw := least(1, greatest(public.cfg_num(v_su, '{awareness,min}', 0.01),
            pc.awareness
            + public.cfg_num(v_su, '{awareness,growthPerQuarter}', 0.3) * pc.awareness * (1 - pc.awareness) * (0.5 + v_quality)
            + v_gain
            - public.cfg_num(v_su, '{awareness,decayPerQuarter}', 0.03) * pc.awareness));

  v_demand := v_qpot * v_aw * (0.5 + 0.5 * v_quality) * exp(public.cfg_num(v_su, '{demandNoise}', 0.1) * public.gauss_random());
  v_cap := (v_team ->> 'team_productivity_bps')::double precision / 10000.0
         * public.cfg_num(v_su, array['capacityCentsPerProductivity', c.sector_key], 250000);
  v_rev := least(v_demand, v_cap);
  v_rev_c := round(v_rev::numeric)::bigint;
  v_cogs := round((v_rev * (1 - public.cfg_num(v_su, array['grossMargin', c.sector_key], 0.5)))::numeric)::bigint;
  v_fixed := (v_tier ->> 'fixedCostCentsPerQuarter')::bigint;
  v_aiw := pc.ai_workers * round(public.cfg_num(v_su, '{aiWorkerCostCentsPerQuarter}', 70000))::bigint;
  v_op := v_rev_c - v_cogs - v_fixed - v_aiw - v_mk;

  -- money (closed system): revenue from the households, costs back to them
  v_acc := public.company_cash_account(p_company);
  v_hh := public.ledger_system_account('households');
  if v_rev_c > 0 then
    v_pay := least(v_rev_c, greatest(0, (select a.balance_cents from public.ledger_accounts a where a.id = v_hh)));
    if v_pay > 0 then
      perform public.ledger_transfer(v_hh, v_acc, v_pay, 'company_revenue', 'Umsatz ' || public.game_quarter_label(q.id),
                                     'company', p_company, k || ':revenue', pc.founder_id);
    end if;
  end if;
  v_costs := v_cogs + v_fixed + v_aiw + v_mk;
  select a.balance_cents into v_cash from public.ledger_accounts a where a.id = v_acc;
  v_pay := least(v_costs, greatest(0, coalesce(v_cash, 0)));
  if v_pay > 0 then
    perform public.ledger_transfer(v_acc, v_hh, v_pay, 'company_costs', 'Kosten ' || public.game_quarter_label(q.id),
                                   'company', p_company, k || ':costs', pc.founder_id);
  end if;
  v_unpaid := v_costs - v_pay;
  v_ai := pc.ai_workers;
  if v_unpaid > 0 then
    v_ai := 0;                                  -- distress: the AI workers are let go
  elsif pc.unpaid_cents > 0 then
    select a.balance_cents into v_cash from public.ledger_accounts a where a.id = v_acc;
    v_settle := least(pc.unpaid_cents, greatest(0, coalesce(v_cash, 0)));
    if v_settle > 0 then
      perform public.ledger_transfer(v_acc, v_hh, v_settle, 'company_costs', 'Offene Rechnungen',
                                     'company', p_company, k || ':settle', pc.founder_id);
    end if;
  end if;

  select coalesce(sum(sp.amount_cents), 0) into v_wages
    from public.salary_payouts sp join public.player_jobs j on j.id = sp.player_job_id
   where j.company_id = p_company and sp.period_end > q.starts_at and sp.period_end <= q.ends_at;

  if v_op > 0 then
    v_xp := public.grant_xp(pc.founder_id, 'company_quarter_profit',
                            public.config_double('progression', '{xpSources,profitableCompanyQuarter,xp}', 500)::integer,
                            'company_quarter:' || p_company::text || ':' || q.id::text, 'company', p_company);
  end if;

  update public.player_companies
     set awareness = v_aw, quality = v_quality, quarters_active = quarters_active + 1, last_closed_quarter_id = q.id,
         unpaid_cents = unpaid_cents + v_unpaid - v_settle,
         distress = (unpaid_cents + v_unpaid - v_settle) > 0,
         ai_workers = v_ai
   where company_id = p_company;

  insert into public.player_company_reports (company_id, game_quarter_id, label, demand_cents, capacity_cents, revenue_cents,
                                             cogs_cents, fixed_cents, ai_worker_cents, marketing_cents, wages_cents,
                                             operating_profit_cents, utilization_bps, paid_costs_cents, unpaid_added_cents,
                                             awareness_bps, quality_bps, team_productivity_bps, team_sector_score)
  values (p_company, q.id, public.game_quarter_label(q.id), round(v_demand::numeric)::bigint, round(v_cap::numeric)::bigint,
          v_rev_c, v_cogs, v_fixed, v_aiw, v_mk, v_wages, v_op,
          round(case when v_cap > 0 then least(1, v_demand / v_cap) else 1 end * 10000)::integer,
          v_pay, v_unpaid, round(v_aw * 10000)::integer, round(v_quality * 10000)::integer,
          (v_team ->> 'team_productivity_bps')::integer, (v_team ->> 'team_sector_score')::integer);

  return jsonb_build_object('company_id', p_company, 'quarter_id', q.id, 'revenue_cents', v_rev_c,
                            'operating_profit_cents', v_op, 'unpaid_added_cents', v_unpaid, 'xp', v_xp);
end;
$$;

-- Closes every closed game quarter a player company has not been through yet
-- (from its founding on, at most 8 per company and run). Called by run_due_jobs().
create or replace function public.player_companies_close_due()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  r   record;
  q   record;
  v_n integer := 0;
begin
  for r in
    select pc.company_id, c.founded_at,
           (select gq.ends_at from public.game_quarters gq where gq.id = pc.last_closed_quarter_id) as last_end
      from public.player_companies pc join public.companies c on c.id = pc.company_id
     order by pc.company_id
  loop
    for q in
      select gq.id from public.game_quarters gq
       where gq.status = 'closed' and gq.ends_at > coalesce(r.last_end, r.founded_at)
       order by gq.ends_at limit 8
    loop
      if (public.player_company_close_quarter(r.company_id, q.id) ->> 'skipped') is null then
        v_n := v_n + 1;
      end if;
    end loop;
  end loop;
  return v_n;
end;
$$;

-- ---------------------------------------------------------------------------
-- RPCs
-- ---------------------------------------------------------------------------
-- The caller's own player company (founder); company_not_found otherwise.
create or replace function public.require_own_company()
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player  uuid := public.require_player();
  v_company uuid;
begin
  select pc.company_id into v_company from public.player_companies pc where pc.founder_id = v_player;
  if v_company is null then
    perform public.api_error('company_not_found');
  end if;
  return v_company;
end;
$$;

create or replace function public.check_company_name(p_name text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_reason text;
begin
  perform public.require_player();
  v_reason := public.name_violation(p_name, 'company');
  return jsonb_build_object('allowed', v_reason is null, 'reason', v_reason);
end;
$$;

create or replace function public.found_company(p_request_id uuid, p_name text, p_idea text, p_sector text, p_color text,
                                                p_tier text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_idea   text := btrim(coalesce(p_idea, ''));
  v_reason text;
  v_tier   jsonb;
  v_level  integer;
  v_cost   bigint;
  v_cash   bigint;
  v_id     uuid := gen_random_uuid();
  v_acc    uuid;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'found_company');
  if v_replay is not null then
    return v_replay;
  end if;
  if not public.rate_limit_hit(v_player, 'player_action',
           greatest(1, public.config_double('abuse', '{rateLimits,actionsPerMinute}', 60))::integer, 60) then
    perform public.api_error('rate_limited');
  end if;
  if coalesce(p_tier, '') not in ('garage', 'small_business')
     or not exists (select 1 from public.sectors s where s.key = p_sector)
     or public.config_jsonb('startups', array['capacityCentsPerProductivity', p_sector]) is null
     or coalesce(p_color, '') !~ '^#[0-9a-fA-F]{6}$'
     or char_length(v_idea) not between 1 and 120 then
    perform public.api_error('invalid_argument');
  end if;
  if public.text_has_profanity(v_idea) then
    perform public.api_error('name_profanity');
  end if;
  perform 1 from public.profiles p where p.id = v_player for update;
  if exists (select 1 from public.player_companies pc where pc.founder_id = v_player) then
    perform public.api_error('company_exists');
  end if;
  if exists (select 1 from public.player_jobs j where j.player_id = v_player and j.status = 'active') then
    perform public.api_error('job_active_exists');
  end if;
  v_reason := public.name_violation(p_name, 'company');
  if v_reason is not null then
    perform public.api_error(v_reason);
  end if;
  v_tier := public.company_tier_cfg(p_tier);
  select p.level into v_level from public.profiles p where p.id = v_player;
  if v_level < (v_tier ->> 'minLevel')::integer then
    perform public.api_error('company_level_too_low');
  end if;
  v_cost := (v_tier ->> 'foundingCostCents')::bigint;
  perform public.lock_player_accounts(v_player);
  select a.balance_cents into v_cash from public.ledger_accounts a where a.owner_player_id = v_player and a.kind = 'player_cash';
  if coalesce(v_cash, 0) < v_cost then
    perform public.api_error('insufficient_funds');
  end if;

  insert into public.companies (id, name, slug, description, sector_key, is_ai, legal_form, phase, founder_id, ceo_id,
                                brand_color, shares_outstanding, max_employees, founded_quarter_id, founded_at)
  values (v_id, p_name, trim(both '-' from lower(regexp_replace(p_name, '[^A-Za-z0-9]+', '-', 'g'))) || '-' || left(v_id::text, 8),
          v_idea, p_sector, false, 'small_business', 'private', v_player, v_player, lower(p_color), 1,
          (v_tier ->> 'maxEmployees')::integer, (public.current_game_quarter()).id, now());
  insert into public.ledger_accounts (kind, owner_company_id, label) values ('company_cash', v_id, 'Firmenkasse')
  returning id into v_acc;
  if v_cost > 0 then
    perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), v_acc, v_cost, 'company_founding',
                                   'Gründung ' || p_name, 'company', v_id, 'found:' || v_id::text, v_player);
  end if;
  insert into public.player_companies (company_id, founder_id, idea, tier, potential_annual_cents, awareness, quality, request_id)
  values (v_id, v_player, v_idea, p_tier, public.startup_potential_from_uniform(1 - random()),
          public.config_double('startups', '{awareness,initial}', 0.03), public.config_double('startups', '{quality,base}', 0.25),
          p_request_id);
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_id)));
end;
$$;

create or replace function public.get_my_company()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid := public.require_player();
begin
  return jsonb_build_object('company', (select public.company_state(pc.company_id) from public.player_companies pc
                                         where pc.founder_id = v_player));
end;
$$;

create or replace function public.set_company_marketing(p_request_id uuid, p_marketing_cents bigint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null or p_marketing_cents is null or p_marketing_cents < 0 or p_marketing_cents > 1000000000 then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'set_company_marketing');
  if v_replay is not null then
    return v_replay;
  end if;
  update public.player_companies set marketing_cents_per_quarter = p_marketing_cents where company_id = v_company;
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;

create or replace function public.set_ai_workers(p_request_id uuid, p_count integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  pc        public.player_companies;
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null or p_count is null or p_count < 0 or p_count > 1000 then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'set_ai_workers');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into pc from public.player_companies where company_id = v_company for update;
  if p_count + (select count(*) from public.player_jobs j where j.company_id = v_company and j.status = 'active')
     > (public.company_tier_cfg(pc.tier) ->> 'maxEmployees')::integer then
    perform public.api_error('employee_limit');
  end if;
  update public.player_companies set ai_workers = p_count where company_id = v_company;
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;

-- Pays open bills from the company cash (deposit, quarter close); clears the distress flag.
create or replace function public.player_company_settle_unpaid(p_company uuid, p_key text)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  pc       public.player_companies;
  v_acc    uuid := public.company_cash_account(p_company);
  v_settle bigint;
begin
  select * into pc from public.player_companies where company_id = p_company for update;
  if pc.unpaid_cents <= 0 then
    return 0;
  end if;
  select least(pc.unpaid_cents, greatest(0, a.balance_cents)) into v_settle from public.ledger_accounts a where a.id = v_acc;
  if v_settle > 0 then
    perform public.ledger_transfer(v_acc, public.ledger_system_account('households'), v_settle, 'company_costs',
                                   'Offene Rechnungen', 'company', p_company, p_key, pc.founder_id);
  end if;
  update public.player_companies
     set unpaid_cents = unpaid_cents - v_settle, distress = unpaid_cents - v_settle > 0
   where company_id = p_company;
  return v_settle;
end;
$$;

create or replace function public.company_deposit(p_request_id uuid, p_amount_cents bigint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  v_cash    bigint;
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null or p_amount_cents is null or p_amount_cents < 1 then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'company_deposit');
  if v_replay is not null then
    return v_replay;
  end if;
  perform public.lock_player_accounts(v_player);
  select a.balance_cents into v_cash from public.ledger_accounts a where a.owner_player_id = v_player and a.kind = 'player_cash';
  if coalesce(v_cash, 0) < p_amount_cents then
    perform public.api_error('insufficient_funds');
  end if;
  perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), public.company_cash_account(v_company),
                                 p_amount_cents, 'capital_injection', 'Einlage', 'company', v_company,
                                 'deposit:' || p_request_id::text, v_player);
  perform public.player_company_settle_unpaid(v_company, 'deposit-settle:' || p_request_id::text);
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;

create or replace function public.company_withdraw(p_request_id uuid, p_amount_cents bigint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  v_free    bigint;
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null or p_amount_cents is null or p_amount_cents < 1 then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'company_withdraw');
  if v_replay is not null then
    return v_replay;
  end if;
  perform 1 from public.player_companies pc where pc.company_id = v_company for update;
  select a.balance_cents - pc.unpaid_cents into v_free
    from public.ledger_accounts a join public.player_companies pc on pc.company_id = a.owner_company_id
   where a.owner_company_id = v_company and a.kind = 'company_cash';
  if coalesce(v_free, 0) < p_amount_cents then
    perform public.api_error('insufficient_funds');
  end if;
  perform public.ledger_transfer(public.company_cash_account(v_company), public.ledger_player_account(v_player, 'player_cash'),
                                 p_amount_cents, 'transfer', 'Entnahme', 'company', v_company,
                                 'withdraw:' || p_request_id::text, v_player);
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;

create or replace function public.upgrade_company(p_request_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  pc        public.player_companies;
  v_sb      jsonb := public.company_tier_cfg('small_business');
  v_cost    bigint;
  v_cash    bigint;
  v_level   integer;
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'upgrade_company');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into pc from public.player_companies where company_id = v_company for update;
  if pc.tier <> 'garage' then
    perform public.api_error('company_upgrade_unavailable');
  end if;
  select p.level into v_level from public.profiles p where p.id = v_player;
  if v_level < (v_sb ->> 'minLevel')::integer then
    perform public.api_error('company_level_too_low');
  end if;
  v_cost := (public.company_state(v_company) ->> 'upgrade_cost_cents')::bigint;
  perform public.lock_player_accounts(v_player);
  select a.balance_cents into v_cash from public.ledger_accounts a where a.owner_player_id = v_player and a.kind = 'player_cash';
  if coalesce(v_cash, 0) < v_cost then
    perform public.api_error('insufficient_funds');
  end if;
  if v_cost > 0 then
    perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), public.company_cash_account(v_company),
                                   v_cost, 'company_conversion', 'Kleinunternehmen', 'company', v_company,
                                   'upgrade:' || v_company::text, v_player);
  end if;
  update public.player_companies set tier = 'small_business' where company_id = v_company;
  update public.companies set max_employees = (v_sb ->> 'maxEmployees')::integer where id = v_company;
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;

create or replace function public.get_company_postings()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_company uuid := public.require_own_company();
begin
  return jsonb_build_object('postings', coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', p.id, 'tier', p.tier, 'title', p.title, 'title_key', p.title_key, 'required', p.required,
             'salary_cents_per_hour', p.salary_cents_per_hour, 'slots', coalesce(p.slots, 1),
             'slots_open', greatest(0, coalesce(p.slots, 1) - (select count(*) from public.player_jobs j
                                                                 where j.posting_id = p.id and j.status = 'active'))::integer,
             'status', p.status,
             'applications_pending', (select count(*) from public.job_applications a
                                       where a.posting_id = p.id and a.status = 'pending')::integer,
             'posted_at', p.posted_at)
             order by p.status = 'closed', p.posted_at desc, p.id)
      from public.job_postings p
     where p.company_id = v_company and (p.status = 'open' or p.updated_at > now() - interval '7 days')), '[]'::jsonb));
end;
$$;

-- ---------------------------------------------------------------------------
-- Wiring: contracts, player card, portfolio, net worth, rich list, jobs
-- ---------------------------------------------------------------------------
-- sign_contract as in M2b; founders cannot take a job (owns_company), player companies respect max employees.
create or replace function public.sign_contract(p_request_id uuid, p_application_id uuid, p_signature text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  a        public.job_applications;
  p        public.job_postings;
  v_scores jsonb;
begin
  v_player := public.require_player();
  if p_request_id is null or p_signature is null or char_length(p_signature) < 1 or char_length(p_signature) > 8000 then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'sign_contract');
  if v_replay is not null then
    return v_replay;
  end if;
  perform 1 from public.profiles pr where pr.id = v_player for update;
  select * into a from public.job_applications where id = p_application_id and player_id = v_player for update;
  if a.id is null then
    perform public.api_error('application_not_found');
  end if;
  if a.status <> 'offered' then
    perform public.api_error('application_not_offered');
  end if;
  if a.offer_expires_at <= now() then
    perform public.api_error('offer_expired');
  end if;
  if exists (select 1 from public.player_jobs j where j.player_id = v_player and j.status = 'active') then
    perform public.api_error('job_active_exists');
  end if;
  if exists (select 1 from public.player_companies pc where pc.founder_id = v_player) then
    perform public.api_error('owns_company');
  end if;
  select * into p from public.job_postings where id = a.posting_id;
  -- player companies: players with an active job there + AI workers <= max employees of the tier
  if exists (select 1 from public.player_companies pc where pc.company_id = p.company_id
                and (select count(*) from public.player_jobs j where j.company_id = pc.company_id and j.status = 'active')
                    + pc.ai_workers + 1 > (public.company_tier_cfg(pc.tier) ->> 'maxEmployees')::integer) then
    perform public.api_error('employee_limit');
  end if;
  if p.slots is not null
     and (select count(*) from public.player_jobs j where j.posting_id = p.id and j.status = 'active') >= p.slots then
    perform public.api_error('job_not_found');
  end if;
  v_scores := public.player_branch_scores(v_player);
  insert into public.player_jobs (player_id, company_id, request_id, tier, title, title_key, required, salary_cents_per_hour,
                                  ceiling_cents_per_hour, raise_base_score, posting_id, application_id, signature,
                                  last_paid_at, started_at, paid_day, paid_minutes_today)
  values (v_player, p.company_id, p_request_id, p.tier, coalesce(p.title, p.title_key), p.title_key, p.required,
          a.offer_salary_cents_per_hour,
          case when p.is_ai then public.ai_salary_ceiling(p.salary_cents_per_hour, public.job_match_score(v_scores, p.required)) end,
          public.job_match_score(v_scores, p.required), p.id, a.id, p_signature,
          public.game_now(), public.game_now(), (public.game_now() at time zone 'Europe/Berlin')::date, 0);
  update public.job_applications set status = 'signed', signature = p_signature where id = a.id;
  update public.job_applications set status = 'closed'
   where player_id = v_player and id <> a.id and status in ('pending', 'offered');
  return public.request_complete(v_player, p_request_id, public.job_state(v_player));
end;
$$;

-- get_player_card as in M2b; company = {name, ticker} for founders
create or replace function public.get_player_card(p_nickname text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  p      public.profiles;
  v_job  jsonb;
begin
  perform public.require_player();
  select * into p from public.profiles x where lower(x.nickname) = lower(btrim(coalesce(p_nickname, ''))) and not x.is_deactivated;
  if p.id is null then
    perform public.api_error('player_not_found');
  end if;
  select jsonb_build_object('company_name', c.name, 'title_key', j.title_key, 'title', case when j.title_key is null then j.title end,
                            'tier', j.tier, 'since', j.started_at)
    into v_job
    from public.player_jobs j join public.companies c on c.id = j.company_id
   where j.player_id = p.id and j.status = 'active';
  return jsonb_build_object(
    'nickname',        p.nickname,
    'avatar_key',      p.avatar_key,
    'level',           p.level,
    'rank',            public.player_rich_rank(p.id),
    'net_worth_cents', public.player_net_worth_cents(p.id),
    'streak_days',     public.player_streak_days(p.id),
    'skills_learned',  (select count(*) from public.player_skills s where s.player_id = p.id)::integer,
    'branch_scores',   public.player_branch_scores(p.id),
    'top_skills',      coalesce((select jsonb_agg(jsonb_build_object('key', x.skill_key, 'tier', x.tier) order by x.tier desc, x.learned_at)
                                   from (select s.skill_key, s.learned_at, (public.skill_node(s.skill_key) ->> 'tier')::integer as tier
                                           from public.player_skills s where s.player_id = p.id
                                          order by 3 desc nulls last, s.learned_at limit 3) x), '[]'::jsonb),
    'job',             v_job,
    'company',         (select jsonb_build_object('name', c.name, 'ticker', c.ticker)
                          from public.player_companies pc join public.companies c on c.id = pc.company_id
                         where pc.founder_id = p.id),
    'member_since',    p.created_at);
end;
$$;

-- get_my_portfolio as in M2b plus company_value_cents
create or replace function public.get_my_portfolio()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player    uuid;
  v_cash      bigint;
  v_reserved  bigint;
  v_positions jsonb;
  v_value     bigint;
  v_bid_value bigint;
  v_orders    jsonb;
  v_trades    jsonb;
  v_prof      public.profiles;
  v_priv      public.player_private;
  v_level     jsonb;
  v_days      double precision := public.config_double('names', '{nicknameChangeDays}', 60);
  v_today     date := (public.game_now() at time zone 'Europe/Berlin')::date;
  v_streak    integer;
  ls          public.login_streaks;
begin
  v_player := public.require_player();
  select coalesce(sum(a.balance_cents) filter (where a.kind = 'player_cash'), 0),
         coalesce(sum(a.balance_cents) filter (where a.kind = 'player_reserve'), 0)
    into v_cash, v_reserved
    from public.ledger_accounts a where a.owner_player_id = v_player;

  select coalesce(jsonb_agg(jsonb_build_object(
           'ticker', x.ticker, 'name', x.name, 'kind', x.kind, 'quantity_e6', x.quantity_e6,
           'reserved_quantity_e6', x.reserved_quantity_e6, 'avg_price_e4', x.avg_entry_price_e4,
           'last_price_e4', x.last_price_e4, 'market_value_cents', x.mv, 'cost_basis_cents', x.cost_basis_cents,
           'unrealized_pnl_cents', x.mv - x.cost_basis_cents, 'realized_pnl_cents', x.realized_pnl_cents,
           'change_bps', x.change_bps, 'opened_at', x.opened_at)
           order by x.mv desc), '[]'::jsonb),
         coalesce(sum(x.mv), 0)::bigint,
         coalesce(sum(x.bv), 0)::bigint
    into v_positions, v_value, v_bid_value
    from (select s.ticker, s.name, s.kind, p.quantity_e6, p.reserved_quantity_e6, p.avg_entry_price_e4, p.cost_basis_cents,
                 p.realized_pnl_cents, p.opened_at, q.last_price_e4, q.change_bps,
                 public.value_cents(p.quantity_e6, q.last_price_e4) as mv,
                 public.value_cents(p.quantity_e6, coalesce(q.bid_e4, q.last_price_e4)) as bv
            from public.positions p
            join public.securities s on s.id = p.security_id
            join public.security_quotes q on q.security_id = p.security_id
           where p.player_id = v_player and p.status = 'open' and p.quantity_e6 > 0) x;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', o.id, 'ticker', s.ticker, 'side', o.side, 'type', o.type, 'quantity_e6', o.quantity_e6,
           'filled_quantity_e6', o.filled_quantity_e6, 'limit_price_e4', o.limit_price_e4, 'status', o.status,
           'reserved_cents', o.reserved_cents, 'created_at', o.created_at)
           order by o.created_at desc), '[]'::jsonb)
    into v_orders
    from public.orders o join public.securities s on s.id = o.security_id
   where o.player_id = v_player and o.status in ('open', 'partially_filled');

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', t.id, 'ticker', t.ticker, 'side', t.side, 'quantity_e6', t.quantity_e6, 'price_e4', t.price_e4,
           'gross_cents', t.gross_cents, 'fee_cents', t.fee_cents, 'tax_cents', t.tax_cents,
           'realized_pnl_cents', t.realized_pnl_cents, 'xp_awarded', t.xp_awarded, 'executed_at', t.executed_at)
           order by t.executed_at desc), '[]'::jsonb)
    into v_trades
    from (select tr.*, s.ticker from public.trades tr join public.securities s on s.id = tr.security_id
           where tr.player_id = v_player order by tr.executed_at desc limit 50) t;

  select * into v_prof from public.profiles where id = v_player;
  select * into v_priv from public.player_private where player_id = v_player;
  select * into ls from public.login_streaks where player_id = v_player;
  v_level := public.level_progress(v_prof.xp_total);
  v_streak := case when ls.last_login_day >= v_today - 1 then ls.current_streak
                   when ls.last_login_day = v_today - 2 and ls.freeze_tokens > 0 then ls.current_streak
                   else 0 end;

  return jsonb_build_object(
    'cash_cents',            v_cash,
    'reserved_cents',        v_reserved,
    'positions_value_cents', v_value,
    'total_cents',           v_cash + v_reserved + v_value,
    'net_worth_cents',       v_cash + v_reserved + v_bid_value,
    'loss_pot_cents',        coalesce(v_priv.tax_loss_pot_cents, 0),
    'vault',                 public.vault_status(v_player) - 'accrued_seconds' - 'base_rate_cents_per_hour',
    'positions',             v_positions,
    'open_orders',           v_orders,
    'recent_trades',         v_trades,
    'level',                 v_prof.level,
    'xp_total',              v_prof.xp_total,
    'xp_into_level',         (v_level ->> 'xp_into_level')::bigint,
    'xp_for_next',           (v_level ->> 'xp_for_next')::bigint,
    'tutorial_completed',    v_priv.tutorial_completed_at is not null,
    'nickname',              v_prof.nickname,
    'nickname_change_available_at',
                             case when v_prof.nickname_changed_at is null
                                    or v_prof.nickname_changed_at + make_interval(secs => v_days * 86400) <= now() then null
                                  else v_prof.nickname_changed_at + make_interval(secs => v_days * 86400) end,
    'missions_claimable',    (select count(*) from public.player_missions m
                               where m.player_id = v_player and m.status = 'completed'
                                 and (m.expires_at is null or m.expires_at > public.game_now()))::integer,
    'streak_days',           coalesce(v_streak, 0),
    'avatar_key',            coalesce(v_prof.avatar_key, 'rookie'),
    'skill_points_free',     coalesce((select sp.free_points from public.player_skill_points sp where sp.player_id = v_player), 0),
    'daily_reward_claimable', not exists (select 1 from public.daily_reward_claims c
                                           where c.player_id = v_player
                                             and c.claim_day = (public.game_now() at time zone 'Europe/Berlin')::date),
    'company_value_cents',   public.player_company_value_cents(v_player),
    'server_time',           public.game_now());
end;
$$;

-- rich list and net worth include the founder's company value
create or replace function public.rich_list_entries()
returns table (entity_kind text, entity_id uuid, name text, description text, net_worth_cents bigint, rank_all integer, rank_players integer)
language sql
stable
security definer
set search_path = ''
as $$
  with players as (
    select p.id,
           coalesce(a.cash, 0) + coalesce(v.val, 0) + coalesce(public.company_value_cents(pc.company_id), 0) as nw,
           p.nickname
      from public.profiles p
      left join (select owner_player_id, sum(balance_cents)::bigint as cash from public.ledger_accounts
                  where owner_player_id is not null group by owner_player_id) a on a.owner_player_id = p.id
      left join (select pos.player_id, sum(public.value_cents(pos.quantity_e6, coalesce(q.bid_e4, q.last_price_e4)))::bigint as val
                   from public.positions pos join public.security_quotes q on q.security_id = pos.security_id
                  where pos.status = 'open' and pos.quantity_e6 > 0 group by pos.player_id) v on v.player_id = p.id
      left join public.player_companies pc on pc.founder_id = p.id
     where not p.is_deactivated
  ), tycoons as (
    select t.id, t.name, t.description,
           t.cash_cents + coalesce(sum(public.value_cents(h.quantity_e6, coalesce(q.bid_e4, q.last_price_e4))), 0)::bigint as nw
      from public.rich_tycoons t
      left join public.rich_tycoon_holdings h on h.tycoon_id = t.id
      left join public.security_quotes q on q.security_id = h.security_id
     group by t.id
  ), allx as (
    select 'player'::text as entity_kind, id as entity_id, nickname as name, null::text as description, nw from players
    union all
    select 'tycoon', id, name, description, nw from tycoons
  )
  select x.entity_kind, x.entity_id, x.name, x.description, x.nw,
         (row_number() over (order by x.nw desc, x.entity_kind, x.entity_id))::integer,
         case when x.entity_kind = 'player'
              then (row_number() over (partition by x.entity_kind order by x.nw desc, x.entity_id))::integer end
    from allx x;
$$;

create or replace function public.player_net_worth_cents(p_player uuid)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select sum(a.balance_cents) from public.ledger_accounts a where a.owner_player_id = p_player), 0)::bigint
       + coalesce((select sum(public.value_cents(p.quantity_e6, coalesce(q.bid_e4, q.last_price_e4)))
                     from public.positions p join public.security_quotes q on q.security_id = p.security_id
                    where p.player_id = p_player and p.status = 'open' and p.quantity_e6 > 0), 0)::bigint
       -- founder's player company (ADR-057): cash - unpaid + earnings value
       + public.player_company_value_cents(p_player);
$$;

-- run_due_jobs as in M2b plus the quarter close of player companies
create or replace function public.run_due_jobs()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now      timestamptz;
  v_result   jsonb := '{}'::jsonb;
  v_closed   jsonb := '[]'::jsonb;
  v_latest   bigint;
  q          record;
  v_run      bigint;
begin
  -- waits for a running tick (ticks only try the lock and skip)
  perform pg_advisory_xact_lock(7311001);
  v_now := public.game_now();
  perform public.ensure_game_quarters(3);

  if not exists (select 1 from public.candles limit 1) or not public.money_genesis_done()
     or not exists (select 1 from public.rich_tycoons) then
    v_result := v_result || jsonb_build_object('bootstrap', public.market_bootstrap());
  end if;

  -- first run on a database: older quarters are skipped, only the latest ended one is closed
  if not exists (select 1 from public.job_runs j where j.job_name = 'quarter_close') then
    select gq.id into v_latest from public.game_quarters gq
     where gq.ends_at <= v_now and gq.status <> 'closed' order by gq.ends_at desc limit 1;
    for q in select gq.id from public.game_quarters gq
              where gq.ends_at <= v_now and gq.status <> 'closed' and gq.id <> coalesce(v_latest, -1)
    loop
      update public.game_quarters set status = 'closed', closed_at = now() where id = q.id;
      insert into public.job_runs (job_name, run_key, status, finished_at, details)
      values ('quarter_close', q.id::text, 'succeeded', now(), '{"skipped": "before_first_run"}'::jsonb)
      on conflict do nothing;
    end loop;
  end if;

  for q in select gq.id from public.game_quarters gq
            where gq.ends_at <= v_now and gq.status <> 'closed'
            order by gq.ends_at limit 8
  loop
    v_closed := v_closed || public.close_game_quarter(q.id);
  end loop;
  v_result := v_result || jsonb_build_object('quarters', v_closed);
  -- player companies: every closed quarter since their founding (ADR-057)
  v_result := v_result || jsonb_build_object('player_company_quarters', public.player_companies_close_due());

  -- bonds that matured between quarter closes (or after a downtime)
  if exists (select 1 from public.bonds bd join public.securities s on s.id = bd.security_id
              where s.status = 'listed' and bd.matures_at <= v_now) then
    v_result := v_result || jsonb_build_object('bonds_redeemed', public.redeem_matured_bonds(v_now));
  end if;
  v_result := v_result || jsonb_build_object('bonds_issued', public.ensure_bond_series());

  -- jobs: AI postings of the running quarter, wages since the last run
  v_result := v_result || jsonb_build_object('job_postings', public.refresh_ai_job_postings(),
                                             'salaries_paid', public.accrue_salaries(null));

  -- rich list snapshot every richList.snapshotMinutes (rank news, 24 h changes, state missions)
  v_result := v_result || jsonb_build_object('rich_list', public.rich_list_snapshot(false));

  -- daily maintenance (first run per UTC day)
  insert into public.job_runs (job_name, run_key) values ('maintenance', to_char(now() at time zone 'UTC', 'YYYY-MM-DD'))
  on conflict (job_name, run_key) do nothing
  returning id into v_run;
  if v_run is not null then
    v_result := v_result || jsonb_build_object('maintenance', public.run_maintenance());
    -- price_ticks: keep about one day (candles hold the history), cron log: one day
    perform public.maintain_price_tick_partitions(3, 1);
    if to_regclass('cron.job_run_details') is not null then
      begin
        execute 'delete from cron.job_run_details where end_time < now() - interval ''1 day''';
      exception when others then
        raise warning 'NEXA: could not prune cron.job_run_details: %', sqlerrm;
      end;
    end if;
    delete from public.job_runs j where j.job_name = 'maintenance' and j.started_at < now() - interval '30 days';
    update public.job_runs set status = 'succeeded', finished_at = now() where id = v_run;
  end if;
  return v_result;
end;
$$;

do $$
declare
  f text;
begin
  foreach f in array array[
    'public.company_tier_cfg(text)', 'public.startup_potential_from_uniform(double precision)', 'public.company_cash_account(uuid)',
    'public.company_value_cents(uuid)', 'public.player_company_value_cents(uuid)', 'public.player_company_team(uuid)',
    'public.uniform_from_text(text)', 'public.game_quarter_label(bigint)', 'public.company_state(uuid)',
    'public.player_company_close_quarter(uuid, bigint)', 'public.player_companies_close_due()', 'public.require_own_company()',
    'public.check_company_name(text)', 'public.found_company(uuid, text, text, text, text, text)', 'public.get_my_company()',
    'public.set_company_marketing(uuid, bigint)', 'public.set_ai_workers(uuid, integer)',
    'public.player_company_settle_unpaid(uuid, text)', 'public.company_deposit(uuid, bigint)',
    'public.company_withdraw(uuid, bigint)', 'public.upgrade_company(uuid)', 'public.get_company_postings()',
    'public.sign_contract(uuid, uuid, text)', 'public.get_player_card(text)', 'public.get_my_portfolio()',
    'public.rich_list_entries()', 'public.player_net_worth_cents(uuid)', 'public.run_due_jobs()'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array[
    'public.check_company_name(text)', 'public.found_company(uuid, text, text, text, text, text)', 'public.get_my_company()',
    'public.set_company_marketing(uuid, bigint)', 'public.set_ai_workers(uuid, integer)', 'public.company_deposit(uuid, bigint)',
    'public.company_withdraw(uuid, bigint)', 'public.upgrade_company(uuid)', 'public.get_company_postings()',
    'public.sign_contract(uuid, uuid, text)', 'public.get_player_card(text)', 'public.get_my_portfolio()'
  ] loop
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end;
$$;

-- ===== supabase/migrations/20261115000100_m3d_schema.sql =====
-- =============================================================================
-- NEXA · M3d · 0100 · Schema: profit-linked pay, insolvency and forced loans,
--                     company chat, work tasks (ADR-052, ADR-058..060)
-- =============================================================================
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- Error keys (M3d: NX053..NX057)
create or replace function public.api_error(p_key text)
returns void
language plpgsql
set search_path = ''
as $$
declare
  v_code text;
begin
  v_code := case p_key
    when 'insufficient_funds'          then 'NX001'
    when 'rate_limited'                then 'NX004'
    when 'forbidden'                   then 'NX006'
    when 'invalid_quantity'            then 'NX007'
    when 'invalid_price'               then 'NX007'
    when 'invalid_argument'            then 'NX007'
    when 'invalid_interval'            then 'NX007'
    when 'not_authenticated'           then 'NX010'
    when 'unknown_security'            then 'NX011'
    when 'not_tradable'                then 'NX012'
    when 'insufficient_position'       then 'NX013'
    when 'order_not_found'             then 'NX014'
    when 'order_not_open'              then 'NX015'
    when 'market_paused'               then 'NX016'
    when 'nothing_to_claim'            then 'NX017'
    when 'locked'                      then 'NX018'
    when 'name_too_short'              then 'NX019'
    when 'name_too_long'               then 'NX019'
    when 'name_invalid_chars'          then 'NX019'
    when 'name_profanity'              then 'NX019'
    when 'name_reserved'               then 'NX019'
    when 'name_taken'                  then 'NX019'
    when 'name_change_too_soon'        then 'NX020'
    when 'order_too_small'             then 'NX021'
    when 'market_illiquid'             then 'NX022'
    when 'mission_not_found'           then 'NX023'
    when 'mission_not_completed'       then 'NX024'
    when 'mission_already_claimed'     then 'NX025'
    when 'avatar_unknown'              then 'NX026'
    when 'avatar_locked'               then 'NX027'
    when 'daily_reward_claimed'        then 'NX028'
    when 'skill_unknown'               then 'NX029'
    when 'skill_learned'               then 'NX030'
    when 'skill_locked'                then 'NX031'
    when 'skill_points_insufficient'   then 'NX032'
    when 'job_not_found'               then 'NX033'
    when 'job_level_too_low'           then 'NX034'
    when 'job_skills_missing'          then 'NX035'
    when 'application_limit'           then 'NX036'
    when 'application_exists'          then 'NX037'
    when 'application_not_found'       then 'NX038'
    when 'application_not_offered'     then 'NX039'
    when 'offer_expired'               then 'NX040'
    when 'job_active_exists'           then 'NX041'
    when 'no_active_job'               then 'NX042'
    when 'raise_too_soon'              then 'NX043'
    when 'raise_too_high'              then 'NX044'
    when 'player_not_found'            then 'NX045'
    when 'employer_only'               then 'NX046'
    when 'company_exists'              then 'NX047'
    when 'company_not_found'           then 'NX048'
    when 'company_level_too_low'       then 'NX049'
    when 'owns_company'                then 'NX050'
    when 'employee_limit'              then 'NX051'
    when 'company_upgrade_unavailable' then 'NX052'
    when 'founding_locked'             then 'NX053'
    when 'not_in_company'              then 'NX054'
    when 'work_task_not_found'         then 'NX055'
    when 'work_task_expired'           then 'NX056'
    when 'work_task_done'              then 'NX057'
    else 'NX007'
  end;
  raise exception using errcode = v_code, message = p_key;
end;
$$;

-- ---------------------------------------------------------------------------
-- A. Profit-linked pay
-- ---------------------------------------------------------------------------
alter table public.player_companies
  add column if not exists pay_factor_bps    integer not null default 10000 check (pay_factor_bps between 0 and 10000),
  add column if not exists distress_quarters integer not null default 0 check (distress_quarters >= 0),
  add column if not exists status            text not null default 'active' check (status in ('active', 'dissolved')),
  add column if not exists dissolved_at      timestamptz;
comment on column public.player_companies.pay_factor_bps is 'Share of the contract wage paid in the running quarter (payFactorBps of the last result before wages).';
comment on column public.player_companies.distress_quarters is 'Consecutive quarter closes with open bills; insolvent at startups.insolvency.graceQuarters.';

-- one ACTIVE company per founder (dissolved companies stay as history)
do $$
begin
  if exists (select 1 from pg_constraint where conname = 'player_companies_founder_id_key'
                and conrelid = 'public.player_companies'::regclass) then
    alter table public.player_companies drop constraint player_companies_founder_id_key;
  end if;
end;
$$;
create unique index if not exists player_companies_active_founder_uq on public.player_companies (founder_id) where status = 'active';
create index if not exists player_companies_founder_idx on public.player_companies (founder_id);
grant select (pay_factor_bps, distress_quarters, status, dissolved_at) on public.player_companies to authenticated;

alter table public.player_company_reports
  add column if not exists base_wages_cents bigint not null default 0,
  add column if not exists bonus_cents      bigint not null default 0,
  add column if not exists pay_factor_bps   integer not null default 10000;
comment on column public.player_company_reports.bonus_cents is 'Bonus paid to the employees at this close (distributeBonus, limited by the cash).';
comment on column public.player_company_reports.pay_factor_bps is 'Pay factor set for the next quarter at this close.';

alter table public.salary_payouts add column if not exists base_amount_cents bigint check (base_amount_cents >= 0);
comment on column public.salary_payouts.base_amount_cents is 'Wage of the period at the contract wage, before the pay factor and a cash shortfall (base wages for the bonus).';

-- ---------------------------------------------------------------------------
-- B. Insolvency, private liability, forced loans
-- ---------------------------------------------------------------------------
alter table public.profiles add column if not exists founding_locked_until timestamptz;
comment on column public.profiles.founding_locked_until is 'After an insolvency no new company until then (startups.insolvency.foundingLockoutDays).';

create table if not exists public.company_dissolutions (
  id                 uuid primary key default gen_random_uuid(),
  company_id         uuid not null references public.companies (id) on delete cascade,
  founder_id         uuid not null references public.profiles (id) on delete cascade,
  company_name       text not null,
  reason             text not null check (reason in ('insolvent', 'closed')),
  unpaid_cents       bigint not null default 0,
  severances_cents   bigint not null default 0,
  total_debt_cents   bigint not null default 0,
  from_company_cents bigint not null default 0,
  from_founder_cents bigint not null default 0,
  loan_cents         bigint not null default 0,
  to_founder_cents   bigint not null default 0,
  employees          integer not null default 0,
  created_at         timestamptz not null default now()
);
alter table public.company_dissolutions enable row level security;
create index if not exists company_dissolutions_founder_idx on public.company_dissolutions (founder_id, created_at desc);
create index if not exists company_dissolutions_company_idx on public.company_dissolutions (company_id);
comment on table public.company_dissolutions is 'Dissolved player companies (insolvency or voluntary close) with the settlement (dissolve()).';

create table if not exists public.player_loans (
  id                uuid primary key default gen_random_uuid(),
  player_id         uuid not null references public.profiles (id) on delete cascade,
  kind              text not null default 'forced' check (kind in ('forced')),
  dissolution_id    uuid references public.company_dissolutions (id) on delete set null,
  principal_cents   bigint not null check (principal_cents > 0),
  outstanding_cents bigint not null check (outstanding_cents >= 0 and outstanding_cents <= principal_cents),
  status            text not null default 'open' check (status in ('open', 'repaid')),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  closed_at         timestamptz
);
alter table public.player_loans enable row level security;
create index if not exists player_loans_player_idx on public.player_loans (player_id, status);
create index if not exists player_loans_dissolution_idx on public.player_loans (dissolution_id);
comment on table public.player_loans is 'Forced private loans after a dissolution (no interest); repaid by withholding a share of every private income (withholdIncome).';

-- ---------------------------------------------------------------------------
-- C. Company chat
-- ---------------------------------------------------------------------------
create table if not exists public.company_messages (
  id         bigint generated always as identity primary key,
  company_id uuid not null references public.companies (id) on delete cascade,
  author_id  uuid references public.profiles (id) on delete set null,
  kind       text not null check (kind in ('player', 'system')),
  body       text not null check (char_length(body) between 1 and 1000),
  created_at timestamptz not null default now(),
  check (kind = 'player' or author_id is null)
);
alter table public.company_messages enable row level security;
create index if not exists company_messages_company_idx on public.company_messages (company_id, id desc);
create index if not exists company_messages_author_idx on public.company_messages (author_id, created_at desc);
comment on table public.company_messages is 'Company chat: members only (founder, players with an active job there). System messages have no author.';

-- member of a player company: founder of the active company or active employee there
create or replace function public.is_company_member(p_company uuid, p_player uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.player_companies pc
                  where pc.company_id = p_company and pc.founder_id = p_player and pc.status = 'active')
      or exists (select 1 from public.player_jobs j
                  where j.company_id = p_company and j.player_id = p_player and j.status = 'active');
$$;

-- System line in a company chat (no-op for companies that are not player companies).
create or replace function public.company_system_message(p_company uuid, p_body text)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.company_messages (company_id, kind, body)
  select p_company, 'system', left(p_body, 1000)
   where exists (select 1 from public.player_companies pc where pc.company_id = p_company);
$$;

-- German money text for system messages: "1.234 €", "-56 €"
create or replace function public.format_eur(p_cents bigint)
returns text
language sql
immutable
set search_path = ''
as $$
  select case when p_cents < 0 then '-' else '' end
      || reverse(regexp_replace(reverse(round(abs(p_cents) / 100.0)::bigint::text), '(\d{3})(?=\d)', '\1.', 'g'))
      || ' €';
$$;

-- ---------------------------------------------------------------------------
-- D. Work tasks
-- ---------------------------------------------------------------------------
create table if not exists public.player_work_tasks (
  id             uuid primary key default gen_random_uuid(),
  player_id      uuid not null references public.profiles (id) on delete cascade,
  player_job_id  uuid not null references public.player_jobs (id) on delete cascade,
  kind           text not null check (kind in ('finance_choice', 'sales_pick', 'analyst_estimate')),
  params         jsonb not null,
  correct_index  smallint not null,
  status         text not null default 'open' check (status in ('open', 'started', 'done', 'expired')),
  choice         smallint,
  correct        boolean,
  xp_awarded     integer not null default 0,
  bonus_cents    bigint not null default 0,
  created_at     timestamptz not null default now(),
  started_at     timestamptz,
  expires_at     timestamptz not null,
  answered_at    timestamptz
);
alter table public.player_work_tasks enable row level security;
create index if not exists player_work_tasks_player_idx on public.player_work_tasks (player_id, created_at desc);
create index if not exists player_work_tasks_job_idx on public.player_work_tasks (player_job_id, created_at desc);
comment on table public.player_work_tasks is 'Work tasks (ADR-059, replaces the unused work_tasks draft). correct_index is hidden (no column grant).';

-- ---------------------------------------------------------------------------
-- RLS
-- ---------------------------------------------------------------------------
do $$
begin
  revoke all on public.company_dissolutions from public, anon, authenticated;
  grant select on public.company_dissolutions to authenticated;
  grant all on public.company_dissolutions to service_role;
  drop policy if exists "owner read" on public.company_dissolutions;
  create policy "owner read" on public.company_dissolutions for select to authenticated using (founder_id = (select auth.uid()));

  revoke all on public.player_loans from public, anon, authenticated;
  grant select on public.player_loans to authenticated;
  grant all on public.player_loans to service_role;
  drop policy if exists "owner read" on public.player_loans;
  create policy "owner read" on public.player_loans for select to authenticated using (player_id = (select auth.uid()));

  revoke all on public.company_messages from public, anon, authenticated;
  grant select on public.company_messages to authenticated;
  grant all on public.company_messages to service_role;
  drop policy if exists "members read" on public.company_messages;
  create policy "members read" on public.company_messages for select to authenticated
    using (exists (select 1 from public.player_companies pc
                    where pc.company_id = company_messages.company_id and pc.founder_id = (select auth.uid()) and pc.status = 'active')
           or exists (select 1 from public.player_jobs j
                       where j.company_id = company_messages.company_id and j.player_id = (select auth.uid()) and j.status = 'active'));

  revoke all on public.player_work_tasks from public, anon, authenticated;
  grant select (id, player_id, player_job_id, kind, params, status, choice, correct, xp_awarded, bonus_cents,
                created_at, started_at, expires_at, answered_at) on public.player_work_tasks to authenticated;
  grant all on public.player_work_tasks to service_role;
  drop policy if exists "owner read" on public.player_work_tasks;
  create policy "owner read" on public.player_work_tasks for select to authenticated using (player_id = (select auth.uid()));

  if not exists (select 1 from pg_trigger where tgname = 'set_updated_at' and tgrelid = 'public.player_loans'::regclass) then
    create trigger set_updated_at before update on public.player_loans for each row execute function public.set_updated_at();
  end if;
end;
$$;

do $$
declare
  f text;
begin
  foreach f in array array['public.is_company_member(uuid, uuid)', 'public.company_system_message(uuid, text)',
                           'public.format_eur(bigint)'] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
end;
$$;

commit;
